INSERT INTO @carregadas (TABELA, COLUNA)
INSERT INTO #PVC VALUES (7281, N'81034776', N'81034776', N'Melhoria para instalação de FSL-2308SA-0021', NULL, N'Others/Outros', N'Problema com antigo fluxostato, para instalação do novo era necessário adequação de conexão na linha de água de selagem da BP-2308SA-32', N'Objetivo realizar adequação para instalação de fluxostato tipo IFM', N'10329', N'01 - Imagens/01 - Antes/7281.jpeg', N'Condição do fluxostato anterior, acumulou resíduo internamente vindo a danificar, necessário substituição.', N'01 - Imagens/02 - Depois/7281.jpeg', N'Melhoria consiste em instalação de instrumento mais robusto IFM, com adaptação de conexão soldada diretamente na linha de água de selagem, possibilitando utilizar redução que temos disponível no kanban.', NULL, N'SIM, problema resolvido, objetivo alcançado, Com a instalação de nossa melhoria, possibilitamos partida da BP-2308SA-32 2 em automático e não tivemos mais paradas da mesma por falha no FSL-2308SA-32', N'Adequar situações de forma segura e planejada ajuda na resolução de nossas pendências.', 0, NULL, N'arantir maior agilidade no processo de entrega dos materiais ao executante, por meio da padronização e identificação adequada das peças.', '2025-12-24T00:00:00.000', '2026-01-01T05:52:19.000', N'81034776', NULL, 1);
INSERT INTO #PVC VALUES (7282, N'81029873', N'547667', N'Suporte dos calços da empilhadeira.', NULL, N'Others/Outros', N'Os calços da empilhadeira eram armazenados de forma inadequada e promoviam um ambiente desorganizado,  sem identificação e que dificultava a localização rápida dos calços.
INSERT INTO #PVC VALUES (7283, N'81029873', N'547667', N'Melhoria nos cabos negativos das máquinas de solda.', NULL, N'Others/Outros', N'Os cabos negativos de solda apresentavam desgaste acelerado e ficavam expostos durante as atividades, gerando riscos de falha operacional e insegurança no ambiente de trabalho.
INSERT INTO #PVC VALUES (7284, N'81029873', N'547667', N'Identificação das escadas.', NULL, N'Others/Outros', N'Escadas sem identificação adequada podem gerar riscos de acidentes, dificultar a orientação dos colaboradores e comprometer a conformidade com normas de segurança.
INSERT INTO #PVC VALUES (7285, N'81063774', N'498537', N'PERFIL H ', NULL, N'Others/Outros', N'Durante o processo de montagem do componente Vertimill, a fixação das engrenagens no eixo era realizada por meio de cintas de corrente entrelaçadas no próprio dispositivo. Esse método tinha como finalidade garantir a estabilidade das engrenagens durante as etapas de alinhamento e posicionamento, prevenindo deslocamentos indesejados ou danos às superfícies de contato.', N'Otimizar o risco  de contato direto na peça', N'10230', N'01 - Imagens/01 - Antes/7285.jpeg', N'Durante o processo de montagem do componente Vertimill, a fixação das engrenagens no eixo era realizada por meio de cintas de corrente entrelaçadas no próprio dispositivo. Esse método tinha como finalidade garantir a estabilidade das engrenagens durante as etapas de alinhamento e posicionamento, prevenindo deslocamentos indesejados ou danos às superfícies de contato.', N'01 - Imagens/02 - Depois/7285.jpeg', N'Dispositivo mecânico em perfil H, fabricado em aço e desenvolvido internamente na oficina, destinado à remoção do acoplamento de baixa rotação do componente Vertimill, como parte do processo de manutenção, garantir a execução da manutenção dentro do prazo, utilizando métodos seguros e eficientes, preservando a integridade da peça e a segurança da equipe.', NULL, N'Garantir a execução da manutenção dentro do prazo, utilizando métodos seguros e eficientes, preservando a integridade da peça e a segurança da equipe.', N'Planejamento de Ferramentas e Importância da Inovação Interna', 0, NULL, N'Uma boa identificação possibilita atuações mais rápidas e assertivas.', '2025-12-30T00:00:00.000', '2026-01-01T11:57:20.000', N'81063774', NULL, 1);
INSERT INTO #PVC VALUES (7286, N'81025448', N'81025448', N'equipment visibilty', NULL, N'Underground/Subterrâneo', N'on 760 level 3 way intersection with blindspots', N'line of sight with other equipment', N'10068', N'01 - Imagens/01 - Antes/7286.jpeg', N'intersections on 760 level were very blind. easily causing equipment collisions', N'01 - Imagens/02 - Depois/7286.jpeg', N'with the use of convex mirrors, the intersection is a lot more visible from all 3 directions', NULL, N'much better equipment flow on levels', N'intersections with heavy equipment need visibilty', 0, NULL, N'N/A', '2025-12-30T00:00:00.000', '2026-01-01T12:03:59.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7287, N'81025448', N'81051729', N'equipment visibilty', NULL, N'Underground/Subterrâneo', N'on 790 level 3 way intersection with blindspots', N'line of sight with other equipment', N'10068', N'01 - Imagens/01 - Antes/7287.jpeg', N'intersections on 790 level were very blind. easily causing equipment collisions', N'01 - Imagens/02 - Depois/7287.jpeg', N'with the use of convex mirrors, the intersection is a lot more visible from all 3 directions', NULL, N'much better equipment flow on levels', N'intersections with heavy equipment need visibilty', 0, NULL, N'REPLICAMOS NOS OUTRO EQUIPAMENTOS QUE NÃO TINHAM A TAMPA, E MANTENDO A ERGONOMIA DOS MESMO.', '2025-12-31T00:00:00.000', '2026-01-01T12:08:24.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7288, N'81025448', N'81025448', N'equipment visibilty', NULL, N'Underground/Subterrâneo', N'on 820 level 3 way intersection with blindspots', N'line of sight with other equipment', N'10157', N'01 - Imagens/01 - Antes/7288.jpeg', N'intersections on 820 level were very blind. easily causing equipment collisions', N'01 - Imagens/02 - Depois/7288.jpeg', N'with the use of convex mirrors, the intersection is a lot more visible from all 3 directions', NULL, N'much better equipment flow on levels', N'intersections with heavy equipment need visibilty', 0, NULL, N'eficiência e praticidade.  ', '2025-12-31T00:00:00.000', '2026-01-01T12:13:13.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7289, N'81025448', N'81025448', N'equipment visibilty', NULL, N'Underground/Subterrâneo', N'on 730 level 3 way intersection with blindspots', N'line of sight with other equipment', N'10068', N'01 - Imagens/01 - Antes/7289.jpeg', N'intersections on 730 level were very blind. easily causing equipment collisions', N'01 - Imagens/02 - Depois/7289.jpeg', N'with the use of convex mirrors, the intersection is a lot more visible from all 3 directions', NULL, N'much better equipment flow on levels', N'intersections with heavy equipment need visibilty', 0, NULL, N'Plant hygiene will be easier to maintain', '2025-12-31T00:00:00.000', '2026-01-01T12:18:16.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7290, N'81029873', N'547667', N'Carro para transporte de peças. ', NULL, N'Others/Outros', N'O transporte manual de peças dentro do setor é realizado de forma pouco eficiente, exigindo esforço físico elevado e aumentando o risco de acidentes e danos às peças. Essa situação impacta a produtividade e a segurança dos colaboradores. É necessário desenvolver uma solução prática que facilite o deslocamento das peças, reduzindo esforço e melhorando a ergonomia no processo.
INSERT INTO #PVC VALUES (7291, N'81025448', N'81051729', N'equipment visibilty', NULL, N'Underground/Subterrâneo', N'on 760 ramp entrance 3 way intersection with blind spots', N'line of sight with other equipment', N'10068', N'01 - Imagens/01 - Antes/7291.jpeg', N'entrance on 760 level were very blind. easily causing equipment collisions', N'01 - Imagens/02 - Depois/7291.jpeg', N'with the use of convex mirrors, the intersection is a lot more visible from all 3 directions', NULL, N'much better equipment flow on levels', N'intersections with heavy equipment need visibilty', 0, NULL, N'We reduced time consuming about 30 minutes by the time.', '2025-12-31T00:00:00.000', '2026-01-01T12:27:57.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7292, N'81025448', N'81030023', N'equipment visibilty', NULL, N'Underground/Subterrâneo', N'on 820 ramp entrance 3 way intersection with blind spots', N'line of sight with other equipment', N'10068', N'01 - Imagens/01 - Antes/7292.jpeg', N'entrance on 820 level were very blind. easily causing equipment collisions', N'01 - Imagens/02 - Depois/7292.jpeg', N'with the use of convex mirrors, the intersection is a lot more visible from all 3 directions', NULL, N'much better equipment flow on levels', N'intersections with heavy equipment need visibilty', 0, NULL, N'We reduced injury risk.', '2025-12-30T00:00:00.000', '2026-01-01T12:28:44.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7293, N'81063774', N'498537', N'DISPOSITIVO DE MONTAGEM DA BOMBA WEIR ', NULL, N'Others/Outros', N'A montagem das buchas da bomba WEIR era realizada utilizando marretas de borracha como ferramenta auxiliar para ajuste das peças. Esse método apresentava riscos de aplicação de força excessiva, podendo ocasionar deformações nas buchas, desalinhamento dos componentes e redução da vida útil do conjunto.', N'Desenvolver e implementar um dispositivo específico para montagem das buchas da bomba WEIR vertical, garantindo aplicação de força controlada e uniforme.', N'10230', N'01 - Imagens/01 - Antes/7293.jpeg', N'A montagem das buchas da bomba WEIR era realizada utilizando marretas de borracha como ferramenta auxiliar para ajuste das peças. Esse método apresentava riscos de aplicação de força excessiva, podendo ocasionar deformações nas buchas, desalinhamento dos componentes e redução da vida útil do conjunto.', N'01 - Imagens/02 - Depois/7293.jpeg', N'Dispositivo para montagem da bomba WEIR vertical na balsa, desenvolvido para realizar o impacto das buchas durante o processo de montagem. O objetivo é evitar esforços excessivos no prensamento, que podem causar danos às buchas durante a instalação.', NULL, N' Montagem manual com marretas → alta variabilidade, risco de danos, falta de controle de força.
INSERT INTO #PVC VALUES (7294, N'81063774', N'81063774', N'Suporte de identificação do guanital 				', NULL, N'Others/Outros', N'Guanital  na área da ferramentaria sem identificação, ocasionando desgaste de tempo significativa para os colaboradores na verificação e determinação da medida correta.', N'visão de 3 segundos ', N'10226', N'01 - Imagens/01 - Antes/7294.jpeg', N'Guanital  na área da ferramentaria sem identificação, ocasionando desgaste de tempo significativa para os colaboradores na verificação e determinação da medida correta.', N'01 - Imagens/02 - Depois/7294.jpeg', N' Fabricado um suporte para inclusão de placas de identificação, proporcionando maior agilidade no processo de entrega do material ao executante.', NULL, N'Problema Identificado: A ausência de suporte para placas de identificação causava atrasos na entrega e dificultava a rastreabilidade do material.
INSERT INTO #PVC VALUES (7295, N'81063774', N'544555', N'Adeguação da área externa com caminho seguro 				', NULL, N'Others/Outros', N'Área externa da oficina, destinada à gestão de componentes, sem rota segura para acesso à praça de resíduos.', N'Realizar o caminho seguro ', N'10226', N'01 - Imagens/01 - Antes/7295.jpeg', N'Área externa da oficina, destinada à gestão de componentes, sem rota segura para acesso à praça de resíduos.', N'01 - Imagens/02 - Depois/7295.jpeg', N'Após a identificação da ausência de um caminho seguro nas áreas externas, foi aberto um chamado para a equipe industrial realizar a criação do acesso, garantindo um ambiente de trabalho seguro e conforme as normas de SSMA.', NULL, N'Antes: Ausência de rota segura → risco elevado de acidentes, não conformidade com normas, baixa ergonomia.
INSERT INTO #PVC VALUES (7296, N'503436', N'503436', N'MONITORAMENTO THE ENDURECE DYNAMOX', NULL, N'Projects/Projetos', N'ANTERIORMENTE TINHAMOS QUE REALIZAR AS COLETAS DEPEDENDO DOS OPERADORES NA FORTA 793 D E 797F. ESPERANDO 1 HORA DE AGUARDO E ATRASANDO A OPERAÇÃO.', N'COLETAR A VIBRAÇÃO DE FORMA SEGURA', N'10015', N'01 - Imagens/01 - Antes/7296.jpeg', N'AS COLETAS ERAM FEITAS PRÓXIMAS DOS EQUIPAMENTOS FUNCIONANDO EM 1400 RPM COM RISCO DE SER ATROPELADO OU BATIDA CONTRA.', N'01 - Imagens/02 - Depois/7296.jpeg', N'AO RELIAZARMOS AS INSTALAÇÕES DOS SENSORES PORTABLES ANTES DE FUNCIONAR O CAMINHÃO BLOQUEANDO E EM SEGUIDA INSTALANDO 10 SENSORES NOS PONTOS DE MONITORAMENTO, PODE SUBIR NA CABINE E COLETAR DE FORMA SEGURA.', NULL, N'SIM MAIOR AGILIDADE E SEGURANÇA NAS COLETAS NA CABINE EVITANDO A EXPOSIÇÃO DOS COLABORADORES A LINHAS DE EXPLOSÃO DE PNEU OU ATROPLEAMENTO.', N'SEGURANÇA E MAIOR AGILIDADE', 2, 1, N'less contamination to deal with', '2025-12-31T00:00:00.000', '2026-01-01T23:51:21.000', N'503436', NULL, 2);
INSERT INTO #PVC VALUES (7297, N'923110', N'81009651', N'Melhoria Pia ', NULL, N'No Replication/Sem replicação', N'Pia onde realizamos preparação das amostragens, sempre na preparação projetava material sobre o piso devido descarga da mesma sem mangueira de direcionamento do material.', N'Eliminar projeção de material no piso, assim evitando retrabalho em 5S.', N'10054', N'01 - Imagens/01 - Antes/7297.jpeg', N'Pia onde realizamos preparação das amostragens, sempre na preparação projetava material sobre o piso, devido descarga da mesma sem mangueira de direcionamento do material.', N'01 - Imagens/02 - Depois/7297.jpeg', N'Foi instalado uma mangueira na descarga da Pia e conectada a mangueira em outra descarga que já é direcionado o material descartado direto para o circuito flotação, tendo em vista que esse material contem teor de CU programado da Usina.', NULL, N'SIM, resolvemos problemas com 5S e ainda direcionamos material com alto teor diretamente para o circuito.', N'Ver e Agir', 0, NULL, N'Problem solved by having the proper material code for the log books displayed in each forklift.', '2026-01-01T00:00:00.000', '2026-01-02T01:34:07.000', N'923110', NULL, 1);
INSERT INTO #PVC VALUES (7298, N'81034776', N'81034776', N'Identificação de blocos peneumáticos.', NULL, N'Others/Outros', N'Blocos pneumáticos dos painéis eletropneumáticos não tem identificação adequada, ', N'Identificar de forma rápida tag dos blocos para atuação.', N'10329', N'01 - Imagens/01 - Antes/7298.jpeg', N'Blocos pneumáticos dos painéis eletropneumáticos não tem identificação adequada, ', N'01 - Imagens/02 - Depois/7298.jpeg', N'Com a adequação da identificação, tornamos nossas atividades mais rápidas e seguras.
INSERT INTO #PVC VALUES (7299, N'81039893', N'81039893', N'Deflector Shield Pug 1/2', NULL, N'No Replication/Sem replicação', N'There was an issue when discharging debris/slurry form the Pug Mills discharge drains that you would get splashed. This was found the first time i had to work on the discharge of Pug 1. ', N'To take away the chances of being splashed', N'10045', N'01 - Imagens/01 - Antes/7299.jpeg', N'The valve was wide open and about a foot from the floor. Once this drain was plugged you would have to pressurize the line with process water, then open the valve quickly to dislodge the debris. This would cause splashing.', N'01 - Imagens/02 - Depois/7299.jpeg', N'Cut a bucket in half and removed the side. The handle is now behind the full side of the bucket. When you open the valve the flow of debris is now directed away from personnel.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal', N'Yes', N'Anything can be improved', 0, NULL, N'Improved ease of use of red chain', '2026-01-02T00:00:00.000', '2026-01-02T12:53:13.000', N'81039893', NULL, 1);
INSERT INTO #PVC VALUES (7300, N'81034166', N'506216', N'TAMPA DO ALTERNADOR ', NULL, N'No Replication/Sem replicação', N'EQUIPAMENTO ESTAVA "RODANDO" SEM A TAMPA DO ALTERNADO PRINCIPAL, COM ISSO ACAVA ENTRANDO POEIRA E SUJEIRA INDESEJADAS NO COMPONENTE, ISSO ACAVA PREJUDICANDO O FUNCIONANDO', N' VEDAR   COMPONENTE, / DIMINUIR FALHAS', N'10140', N'01 - Imagens/01 - Antes/7300.jpeg', N'EQUIPAMENTO ESTAVA SEM TAMPA OCASIONANDO SUJEIRAS E FALHAS NO COMPONENTE, ESTAVA SEM VEDAÇÃO ADEQUADA DO LADO ESQUERDO E LADO DIREITO, PODENDO ATE MESMO PERDER AS ESCOVAS DO ALTERNADOR PRINCIPAL', N'01 - Imagens/02 - Depois/7300.jpeg', N'REALIZADA A FABRICAÇÃO, PINTURA, E OS ENGATES, QUE FORAM PEGOS DE UMA CAIXA DE BATERIA QUE IAMOS JOGAR FORA E APROVEITAMOS PARA POR NA TAMPA, DO TAMPA DO ALTERNADO PRINCIPAL.', NULL, N'MELHORIA NA TAMPA E VEDAÇÃO PARA MANTER A VIDA UTIL DO COMPONENTE', N'MELHORAR NOSSO AMBIENTE DE TRABALHO E A VIDA UTIL DO NOSSOS EQUIPAMENTOS', 0, NULL, N'REALIZADO A FABRICAÇÃO E MONTAGEM DA CORTINA DE BORRACHA E REDUZIDO A POLUIÇÃO ATMOSFÉRICA.', '2026-01-01T00:00:00.000', '2026-01-02T14:52:55.000', N'81034166', NULL, 1);
INSERT INTO #PVC VALUES (7301, N'81034166', N'545926', N'dobradiça de pino para porta do gabinete', NULL, N'No Replication/Sem replicação', N'a porta do gabinete estava quebrada e não conseguíamos abrir, e quando foi aberta o trinco estava desgastado ', N'fechar a porta/ vedação', N'10140', N'01 - Imagens/01 - Antes/7301.jpeg', N'pino da porta estava desgastado, não conseguíamos abrir a porta, e tínhamos que por força para retirar a porta e pôr no lugar.', N'01 - Imagens/02 - Depois/7301.jpeg', N'usamos apenas um parafuso que tínhamos na área sem necessidade de comprar um pino novo, limpamos o local, tiramos as ferrugens e lubrificamos o local, e assim a porta do gabinete abri-o e fechou normalmente sem a necessidade de força excessiva.', NULL, N'o problema foi resolvido e com isso podemos replicar em outros equipamentos sem problema algum, ajudando a facilitar a abertura do gabinete', N'melhoria continua', 0, NULL, N'padronização, 5s, sentimento de dono', '2026-01-01T00:00:00.000', '2026-01-02T15:16:26.000', N'81034166', NULL, 1);
INSERT INTO #PVC VALUES (7302, N'607646', N'607646', N'Install a permanent 50-7 filtrate containment ', NULL, N'Refining/Refino', N'When filtering 50-7 filtrate samples are required. when taking the sample spillage occurs on the floor if a containment isn''t available', N'Prevent spillage in workplace', N'10114', N'01 - Imagens/01 - Antes/7302.jpeg', N'Operators often take samples without a pail available and allow the filtrate to spill on the floor', N'01 - Imagens/02 - Depois/7302.jpeg', N'A pail has been secured to 50-7 press so it is always available to collect excess filtrate.  The filtrate can then be dumped into the press hopper eliminating spillage on the floor.', NULL, N'A pail will now be readily available as it is chained to the 50-7 press, and this will prevent spillage and increase plant hygiene', N'Operations will contain the filtrate if a pail is easily accessible but won''t take the time to find one for this purpose', 0, NULL, N'AÇÃO, VER A E AGIR COM SEGURANÇA', '2026-01-01T00:00:00.000', '2026-01-02T16:56:25.000', N'607646', NULL, 1);
INSERT INTO #PVC VALUES (7303, N'87000312', N'87000393', N'To install inspection hole to the dust collecting pipeline of No3 ESP', NULL, N'Refining/Refino', N'Inspection hole was not enough. So, It took long time to collect residue dust in the duct.', N'To reduce workload', N'0', N'01 - Imagens/01 - Antes/7303.jpeg', N'Inspection hole was not enough. At that time, we use rod to collect dust from the duct. But, It took long time to collect residue dust in the duct.', N'01 - Imagens/02 - Depois/7303.jpeg', N'Installed new inspection hole on the dust collecting pipeline of No3 ESP. So, we can reduce time by that activity.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Aumento na performance do equipamento, com ganho no tempo de operação sem falhas.', '2026-01-02T00:00:00.000', '2026-01-03T06:40:36.000', N'87000312', NULL, 1);
INSERT INTO #PVC VALUES (7304, N'87000312', N'87000317', N'Relocate duct collecting nozzle on the No2 matte mixer', NULL, N'Refining/Refino', N'Defect', N'To prevent chocking problem of the No2 AMF', N'0', N'01 - Imagens/01 - Antes/7304.jpeg', N'The dust collecting nozzle was located on the end of mixer. So, adhere lump Ni on the duct was often fallen to the mixer. The lump was often chocked at the discharge line of the 2AMF. ', N'01 - Imagens/02 - Depois/7304.jpeg', N'Relocate duct collecting nozzle on the No2 matte mixer. Thanks to the relocation lump is broken by the mixer before AMF. We can reduce work load to solve it.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'VER E AGIR, CONFIABILIDADE NA PRODUÇÃO.', '2026-01-02T00:00:00.000', '2026-01-03T07:10:01.000', N'87000312', NULL, 1);
INSERT INTO #PVC VALUES (7305, N'87000312', N'87000377', N'Remodeling handrail near the BQ machine', NULL, N'Refining/Refino', N'Defect', N'To improve safety for transporting spare parts of BQ machine', N'0', N'01 - Imagens/01 - Antes/7305.jpeg', N'When transporting spare parts is used Hoist crane bur handrail near the BQ machine was preventing transporting smoothly. So, it had a injury risk about fallen down the parts from high place.', N'01 - Imagens/02 - Depois/7305.jpeg', N'Handrail is remodeled to demountable type. Thanks to the remodeling transporting activity is much safer than before.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'lessen the chance of collisions', '2026-01-02T00:00:00.000', '2026-01-03T07:16:12.000', N'87000312', NULL, 1);
INSERT INTO #PVC VALUES (7306, N'1008564', N'1008564', N'New Gas Monitor Sign Out Sheet', NULL, N'Refining/Refino', N'The old sign out required the addition of the Serial Number.', N'To make sign out sheet more streamlined ', N'0', N'01 - Imagens/01 - Antes/7306.jpeg', N'Worker had to fill in the serial number of gas monitor.', N'01 - Imagens/02 - Depois/7306.jpeg', N'The sign out sheet has been changed with the serial number automatically on the sheet.', NULL, N'Yes', N'Ease of use of the sheet', 0, NULL, N'Eliminar falhas e diminuir ações corretivas.', '2026-01-02T00:00:00.000', '2026-01-03T09:21:18.000', N'1008564', NULL, 1);
INSERT INTO #PVC VALUES (7307, N'81034443', N'483171', N'Suporte para o cooler de água mineral. ', NULL, N'Others/Outros', N'Era posto no chão o cooler e os fardos de água mineral, o que podia causar dificuldade de acesso, desconforto ergonômico, risco de contaminação, desorganização do espaço e possíveis danos aos recipientes. Dessa forma, torna-se necessário e o desenvolvimento de uma solução simples, acessível e eficiente que melhora a organização e o uso adequado desses itens. ', N'Melhorar a ergonômia, padronização do box.', N'10140', N'01 - Imagens/01 - Antes/7307.jpeg', N'Era posto no chão o cooler e os fardos de água mineral, o que podia causar dificuldade de acesso, desconforto ergonômico, risco de contaminação, desorganização do espaço e possíveis danos aos recipientes. ', N'01 - Imagens/02 - Depois/7307.jpeg', N'Após a confecção do suporte, destaca-se a melhoria da ergonomia, pois o cooler fica em uma altura adequada, evitando que as pessoas precisem se abaixar para utilizá-lo.
INSERT INTO #PVC VALUES (7308, N'81034443', N'81034443', N'Suporte com corrente para Fixação Segura do Tambor de Graxa da propulsora de completar. ', NULL, N'Others/Outros', N'A ausência do suporte com corrente pode resultar em movimentação ou tombamento do tambor, causando risco de acidentes com colaboradores, vazamento de graxa, contaminação do ambiente, danos ao equipamento e possíveis paradas de processo. Além disso, aumenta o risco de lesões físicas, como esmagamentos e quedas, comprometendo a segurança no local de trabalho.', N'Garantir segurança e estabilidade do tambor de graxa, evitando movimentações indevidas durante o uso, transporte ou operação. ', N'10140', N'01 - Imagens/01 - Antes/7308.jpeg', N'A ausência do suporte com corrente pode resultar em movimentação ou tombamento do tambor, causando risco de acidentes com colaboradores, vazamento de graxa, contaminação do ambiente, danos ao equipamento e possíveis paradas de processo. Além disso, aumenta o risco de lesões físicas, como esmagamentos e quedas, comprometendo a segurança no local de trabalho.', N'01 - Imagens/02 - Depois/7308.jpeg', N'Instalação de uma corrente de fixação lateral no suporte do tambor de graxa, garantindo a estabilidade e segurança, evitando movimentações, tombamento do tambor e possíveis vazamentos durante a operação. Diminuindo os riscos de lesões físicas, como esmagamento e quedas de materiais, além de diminuir a contaminação do meio ambiente. ', NULL, N'A ausência do suporte com corrente pode resultar em movimentação ou tombamento do tambor, causando risco de acidentes com colaboradores, vazamento de graxa, contaminação do ambiente, danos ao equipamento e possíveis paradas de processo. Além disso, aumenta o risco de lesões físicas, como esmagamentos e quedas, comprometendo a segurança no local de trabalho.', N'Foi possível compreender a importância de identificar riscos no dia a dia, adotar soluções simples e eficazes e agir de forma preventiva para garantir a segurança dos operadores.', 0, NULL, N'lessen the chance of collisions', '2026-01-02T00:00:00.000', '2026-01-03T17:33:46.000', N'81034443', NULL, 1);
INSERT INTO #PVC VALUES (7309, N'1010856', N'1010856', N'sample tray drains', NULL, N'Others/Outros', N'slurry and build up in sample trays', N'sample tray drain holes', N'0', N'01 - Imagens/01 - Antes/7309.jpeg', N'slurry and dust accumulating in trays from samples', N'01 - Imagens/02 - Depois/7309.jpeg', N'added drain holes so slurry and debris can be easily drained and flushed away', NULL, N'yes the sample trays are now easier to keep clean', N'cleanliness', 0, NULL, N'Garantir a realização do checklist de escada antes de cada uso;
INSERT INTO #PVC VALUES (7310, N'1010008', N'1010008', N'Forklift Daily Inspection Book Re-order', NULL, N'No Replication/Sem replicação', N'Finding new Inspection log books for our forklifts took time to go through SAP to find the information needed.  A quick label in each forklift with the material code for these books saves time and makes reordering easier.', N'Easily find the Mat Code to reorder log books', N'0', N'01 - Imagens/01 - Antes/7310.jpeg', N'Finding the material code required to reorder new log books took time to dig through SAP for the info.  ', N'01 - Imagens/02 - Depois/7310.jpeg', N'A simple label in each forklift showing the reorder material code saves time.', NULL, N'Problem solved by having the proper material code for the log books displayed in each forklift.', N'No need to waste time searching for material code', 0, NULL, N'AÇÃO, POIS, TEM COMO OBJETIVO MELHORAR A COFIABILIDADE DA MANUTENÇÃO.', '2025-12-24T00:00:00.000', '2026-01-03T23:46:40.000', N'1010008', NULL, 1);
INSERT INTO #PVC VALUES (7311, N'81015023', N'493579', N'ARMAZENAMENTO DE CILINDROS DE EXTINTORES', NULL, N'No Replication/Sem replicação', N'EXTINTORES ENCONTRAVA-SE ESPALHADOS NO PISO , PODENDOR OCASIONAR UM ACIDENTE OU DANIFICAR  EQUIPAMENTOS DE PRIMEIROS SOCORROS.', N'ARMAZENAR  CILINDROS DE EXTINTORES', N'10263', N'01 - Imagens/01 - Antes/7311.jpeg', N'EXTINTORES ENCONTRAVA-SE ESPALHADOS NO PISO , PODENDOR OCASIONAR UM ACIDENTE OU DANIFICAR  EQUIPAMENTOS DE PRIMEIROS SOCORROS.', N'01 - Imagens/02 - Depois/7311.jpeg', N'REALIZADO A FABRICAÇÃO DE UM SUPORTE PARA ARMAZENAMENTO DOS EXTINTORES , DEIXANDO A ÁREA ORGANIZADA SEM RISCOS DE ACIDENTES E PROTEGENDO OS EQUIPAMENTOS DE PRIMEIROS SOCORROS.', NULL, N'PROBLEMA RESOLVIDO COM A FABRICAÇÃO DO SUPORTE.', N'ORGANIZAÇÃO E ARMAZENAMENTOS ADEQUADOS.', 0, NULL, N'Eliminação das batidas manuais, redução dos riscos de projeção de materiais e riscos ergonômicos, aumento da segurança dos colaboradores, padronização da atividade e melhoria na eficiência e confiabilidade do processo de manutenção.', '2025-12-11T00:00:00.000', '2026-01-04T03:00:57.000', N'81015023', NULL, 1);
INSERT INTO #PVC VALUES (7312, N'81053728', N'81053728', N'Red chain for lifting floc', NULL, N'Others/Outros', N'Using red chain around lifting area was cumbersome with no good place to attach chain in multiple places.', N'Improve ease of use of red chain', N'0', N'01 - Imagens/01 - Antes/7312.jpeg', N'Using red chain around lifting area was cumbersome with no good place to attach chain in multiple places. Chain reel was in place but red tape was often used instead as it was easier to install.', N'01 - Imagens/02 - Depois/7312.jpeg', N'Used magnetic eyelets and carabiners to make dedicated locations for attaching red chain for ease of use, making good safety practices more convenient for the team.', NULL, N'Improved ease of use of red chain', N'0', 0, NULL, N'melhora na segurança', '2026-01-03T00:00:00.000', '2026-01-04T03:50:58.000', N'81053728', NULL, 1);
INSERT INTO #PVC VALUES (7313, N'81015023', N'81015023', N'CURTINA DE VEDAÇÃO', NULL, N'Others/Outros', N'VAZAMENTO DE PO NO CHUTE DE DESCARGA DA CORREIA TRANSPORTADORA  GERANDO POLUIÇÃO ATMOSFÉRICA.', N'DIMINUIR POLUIÇÃO NA  ATMOSFERA', N'10170', N'01 - Imagens/01 - Antes/7313.jpeg', N'VAZAMENTO DE PO NO CHUTE DE DESCARGA DA CORREIA TRANSPORTADORA  GERANDO POLUIÇÃO ATMOSFÉRICA.', N'01 - Imagens/02 - Depois/7313.jpeg', N'REALIZADO FABRICAÇÃO E MONTAGEM DE CORTINA DE BORRACHA PARA REDUZIR POLUIÇÃO ATMOSFÉRICA.', NULL, N'REALIZADO A FABRICAÇÃO E MONTAGEM DA CORTINA DE BORRACHA E REDUZIDO A POLUIÇÃO ATMOSFÉRICA.', N'REDUZIR', 0, NULL, N'Relatório operacional elaborado no Google Keep, permitindo atualização on-line e simultânea por todos os membros da equipe.', '2026-01-03T00:00:00.000', '2026-01-04T03:52:54.000', N'81015023', NULL, 1);
INSERT INTO #PVC VALUES (7314, N'81034166', N'81034166', N'CAROMETRO DE FERRAMENTAS', NULL, N'No Replication/Sem replicação', N'UTILIZAVAMOS UM CADERNO PARA POR OS NOMES E AS FERRAMENTAS, ACABAVAMOS ESQUECENDO DE REPOR AS FERRAMENTAS E ELAS FICAVAM PERDIDAS.', N'ORGANIZAÇÃO/PADRONIZAR', N'10140', N'01 - Imagens/01 - Antes/7314.jpeg', N'Utilizávamos um caderno para anotações das ferramentas; porém, o controle não era eficaz. A organização era deficiente e as ferramentas não retornavam ao local correto.', N'01 - Imagens/02 - Depois/7314.jpeg', N'Com a melhoria implementada, a organização e a padronização foram aprimoradas. O controle passou a ser feito por meio de carômetro, com matrícula, data e ferramenta utilizada, identificando o colaborador que empresta e o que recebe.
INSERT INTO #PVC VALUES (7315, N'81034166', N'81050920', N'MESA PARA REPAROS', NULL, N'No Replication/Sem replicação', N'USAVAMOS A MESA DE PREVENTIVA PARA REALIZAR REPAROS NOS COMPONETES, DESPADRONIZANDO E BABUNÇANDO O LOCAL DE PREVENTIVA.', N'ERGONOMIA/EFICIENCIA', N'10140', N'01 - Imagens/01 - Antes/7315.jpeg', N'USAVAMOS A MESA DE PREVENTIVA PARA REALIZAR REPAROS E NÃO TINHAMOS MORSA, DIFICULTANDO O REPARO DAS PEÇAS.', N'01 - Imagens/02 - Depois/7315.jpeg', N'FABRICADA UMA BANCADA, PINTADA E INDENTIFICADA PARA REALIZAR REPAROS E SOLDADO UMA MORSA PARA FACILITAR A MANUTENÇÃO.', NULL, N'FICOU MUITO MAIS PRATICO A REALIZAÇÃO DE MANUTENÇÃO NAS PEÇAS, E FOI PADONIZADA.', N'ORGANIZAÇÃO E EFICIENCIA', 0, NULL, N'Redução do tempo de parada da moagem para substituição de mangas em 5h/parada. O ganho em segurança é a redução na exposição de pessoas em espaço confinado em área classificada.', '2026-01-03T00:00:00.000', '2026-01-04T14:18:16.000', N'81034166', NULL, 1);
INSERT INTO #PVC VALUES (7316, N'81022586', N'549159', N'Padronização dos fluxostatos da usina salobo III.', NULL, N'Others/Outros', N'Chave de fluxo utilizada no processo não era adequada para o cenário que exigia um grau de proteção elevado. Causando um numero elevado de falhas e trocas rotineiras do instrumento por avaria.', N'Melhorar a qualidade do processo diminuindo falhas. ', N'10197', N'01 - Imagens/01 - Antes/7316.jpeg', N'Chave de fluxo utilizada no processo não era adequada para o cenário que exigia um grau de proteção elevado. Causando um numero elevado de falhas e trocas rotineiras do instrumento por avaria, causando custos e paradas no processo.', N'01 - Imagens/02 - Depois/7316.jpeg', N'Realizada adaptação na tubulação de agua para instalação de nova chave de fluxo do modelo IFM, mais robusta e com grau de proteção superior a instalada anteriormente. ', NULL, N'Aumento na performance do equipamento, com ganho no tempo de operação sem falhas.
INSERT INTO #PVC VALUES (7317, N'81034166', N'81050920', N'PLACA DOS ASPESORES', NULL, N'No Replication/Sem replicação', N'A PLACA DOS ASPESORES QUEBROU E NÃO TINHA NO SITE, COM ISSO O EQUIPAMENTO FICOU INAPTO', N'EFICIENCIA/MELHORIA', N'10140', N'01 - Imagens/01 - Antes/7317.jpeg', N'O EQUIPAMENTO ESTAVA SEM A SUA PLACA E COM ISSO O EQUIPAMENTO VEIO A PARAR EM CORRETIVA, E MOSTRANDO INEFICIÊNCIA PARA SER OPERADO.', N'01 - Imagens/02 - Depois/7317.jpeg', N'REALIZADA FABRICAÇÃO DA PLACA DOS ASPESORES, MELHORANDO A COFIABILIDADE DO EQUIPAMENTO E SENDO APTO PARA A OPERAÇÃO.', NULL, N'MELHORIA NO FUNCIONAMENTO DO EQUIPAMENTO', N'MELHORIA COTINUA', 0, NULL, N'0,5 horas', '2026-01-03T00:00:00.000', '2026-01-04T15:08:02.000', N'81034166', NULL, 1);
INSERT INTO #PVC VALUES (7318, N'81025448', N'81025448', N'underground collision', NULL, N'Underground/Subterrâneo', N'visibility from equipment at intersections is very limited ', N'eliminate the hazard', N'10068', N'01 - Imagens/01 - Antes/7318.jpeg', N'very limited visibility at underground intersections', N'01 - Imagens/02 - Depois/7318.jpeg', N'installed mirrors at crossover 7 exit to create a great visual of traffic coming up or down ramp', NULL, N'vastly improved ', N'need better visibility underground at intersections', 0, NULL, N'Ergonomicamente mais eficiente ', '2026-01-03T00:00:00.000', '2026-01-04T15:09:20.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7319, N'81022586', N'549159', N'Padronização dos fluxostatos da usina salobo III.', NULL, N'Others/Outros', N'Chave de fluxo utilizada no processo não era adequada para o cenário que exigia um grau de proteção elevado. Causando um numero elevado de falhas e trocas rotineiras do instrumento por avaria.
INSERT INTO #PVC VALUES (7320, N'81025448', N'81051729', N'underground collision', NULL, N'Underground/Subterrâneo', N'visibility from equipment at intersections is very limited ', N'eliminate the hazard', N'10068', N'01 - Imagens/01 - Antes/7320.jpeg', N'very limited visibility at underground intersections', N'01 - Imagens/02 - Depois/7320.jpeg', N'installed mirrors at 850 level bay exit to create a great visual of traffic coming up or down ramp', NULL, N'vastly improved ', N'need better visibility underground at intersections', 0, NULL, N'We improved defect.', '2026-01-03T00:00:00.000', '2026-01-04T15:19:10.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7321, N'81025448', N'81025448', N'underground collision', NULL, N'Underground/Subterrâneo', N'visibility from equipment at intersections is very limited ', N'eliminate the hazard', N'10068', N'01 - Imagens/01 - Antes/7321.jpeg', N'very limited visibility at underground intersections', N'01 - Imagens/02 - Depois/7321.jpeg', N'installed mirrors at 700 maintenance bay exit to create a great visual of traffic coming up or down ramp', NULL, N'vastly improved ', N'need better visibility underground at intersections', 0, NULL, N'Atualmente temos uma plataforma fixa e segura para realizar nossas atividades', '2026-01-03T00:00:00.000', '2026-01-04T15:20:06.000', N'81025448', NULL, 1);
INSERT INTO #PVC VALUES (7322, N'81034443', N'81034443', N'Padronização e Disponibilidade Visual do Checklist de Escada.', NULL, N'Others/Outros', N'O checklist de escada era realizado em papel solto, fora do ponto de uso.
INSERT INTO #PVC VALUES (7323, N'81034166', N'81050920', N'MESA PARA PREVENTIVA', NULL, N'No Replication/Sem replicação', N'MESA NÃO TINHA DEMARCAÇÃO PARA PREVENTIVA, EX:FILTRO, MATERIAS E BACLOGS, FICANDO TUDO MISTURADO E ACABANDO NÃO SENDO APLICADOS OS DE PREVENTIVAS.', N'5S/ PADRONIZAÇÃO', N'10140', N'01 - Imagens/01 - Antes/7323.jpeg', N'MESA NÃO TINHA DEMARCAÇÃO PARA PREVENTIVA, EX:FILTRO, MATERIAS E BACLOGS, FICANDO TUDO MISTURADO E ACABANDO NÃO SENDO APLICADOS OS DE PREVENTIVAS, E RISCANDO A MESA.', N'01 - Imagens/02 - Depois/7323.jpeg', N'FOI POSTO NA MESA DE PREVENTIVA, UMA BORRACHA, FEITO DEMARCAÇÃO COM MATERIAL DE FERRO, PINTADO E POSTO TAG EM CADA DEMARCAÇÃO.
INSERT INTO #PVC VALUES (7324, N'92000179', N'81058659', N'Dispositivo Saque da Porca Quadrada do Acumulador de Nitrogênio ', NULL, N'Others/Outros', N'Antes da implementação do dispositivo, para utilizar o nitrogênio era necessário realizar batidas manuais para o saque da porca quadrada do acumulador. Essa prática expunha os colaboradores a risco de projeção de materiais, além de risco ergonômico devido ao esforço físico excessivo e postura inadequada, aumentando a probabilidade de acidentes e lesões.', N'Eliminar esforço manual dos colaboradores', N'10230', N'01 - Imagens/01 - Antes/7324.jpeg', N'Antes do KAIZEN, o saque da porca quadrada do acumulador de nitrogênio era realizado por meio de batidas manuais, sem um dispositivo adequado. Essa prática gerava risco de projeção de materiais, risco ergonômico devido ao esforço físico e à postura inadequada, além de falta de padronização e maior probabilidade de acidentes durante a atividade.', N'01 - Imagens/02 - Depois/7324.jpeg', N'Foi desenvolvido um dispositivo adequado que padronizou o saque da porca e o teste de estanqueidade, eliminando métodos improvisados, reduzindo riscos de projeção de materiais e esforço ergonômico, e proporcionando mais segurança na atividade.', NULL, N'Sim. Com a implementação do dispositivo específico e a padronização do processo, a necessidade de batidas manuais foi eliminada, reduzindo os riscos de projeção de materiais e riscos ergonômicos, tornando a atividade mais segura e controlada.', N'A padronização aliada ao uso de ferramentas corretas elimina práticas inseguras', 0, NULL, N'More accurate and visible tracking of hoist work', '2026-01-04T00:00:00.000', '2026-01-05T05:42:47.000', N'92000179', NULL, 1);
INSERT INTO #PVC VALUES (7325, N'81037003', N'479348', N'base de reforço hidráulico ', NULL, N'Others/Outros', N'a base não estava atendendo o padrão do dispositivo ', N'Realizar uma fabricação de uma nova base', N'10031', N'01 - Imagens/01 - Antes/7325.jpeg', N'Foi projetado uma base para instalação do guincho e a mesma se encontrava com algumas falhas de segurança ', N'01 - Imagens/02 - Depois/7325.jpeg', N'Foi realizado a fabricação de uma nova base para suporte de um hidráulico   ', NULL, N'Conseguimos solucionar o problema de acordo com o planejado ', N'segurança', 0, NULL, N'Resultado foi satisfatoriio', '2025-12-16T00:00:00.000', '2026-01-05T11:36:48.000', N'81037003', NULL, 1);
INSERT INTO #PVC VALUES (7326, N'997932', N'997932', N'Otimização do Relatório de turno. ', NULL, N'Others/Outros', N'Relatório pelo Word somente uma pessoa por vez tem acesso para  realizar  a atualização das informações.', N'Todos terem acesso e controle do relatório online.', N'10054', N'01 - Imagens/01 - Antes/7326.jpeg', N'Relatório no Word elaborado pera operação, permite atualização apenas um usuário por vez, impossibilitando atualização simultânea pelos membros da equipe.
INSERT INTO #PVC VALUES (7327, N'81035407', N'81046967', N'IMPLEMENTO DE ACIONAMENTO A AR ', NULL, N'No Replication/Sem replicação', N'A Lubrificação das colunas do Kimbo eram feitas com a propulsora Manual
INSERT INTO #PVC VALUES (7328, N'74194', N'74194', N'Identificação precisa de mangas furadas no filtro da moagem', NULL, N'Smelting/Fundição', N'Dificuldade para identificar local com mangas furadas durante inspeção no interior do filtro da moagem de carvão para executar a substituição das mesmas.', N'Reduzir o tempo de parada da moagem por dificuldade na identificação do local das mangas furadas no filtro em 2h até jan/26', N'10297', N'01 - Imagens/01 - Antes/7328.jpeg', N'Não há um local que mostre a condição normal x anormal e os locais com mangas furadas no filtro da moagem. É feita inspeção em todo o interior do filtro para encontrar o local com mangas furadas. Isso demanda muito tempo, substituição desnecessária de mangas e pode trocar mangas em local errado perdendo todo o trabalho.', N'01 - Imagens/02 - Depois/7328.jpeg', N'Criada tela no supervisório mostrando o local exato das mangas furadas no filtro da moagem. A cor vermelha indica vazamento acima do limite permitido e mostra o tag das flautas onde estão as mangas danificadas.
INSERT INTO #PVC VALUES (7329, N'607404', N'607404', N'Emergency Cabinet Replacements', NULL, N'Refining/Refino', N'The existing cabinets were all rusty and items inside were old and unusable', N'Ensure emergency cabinets get replaced when in certain condition', N'10193', N'01 - Imagens/01 - Antes/7329.jpeg', N'Existing cabinets were rusty, there is no clear instruction on when to replace the cabinets', N'01 - Imagens/02 - Depois/7329.jpeg', N'New cabinets installed throughout the building, instruction to also note the condition of the cabinet when it gets rusty and can pose a safety hazard', NULL, N'4 cabinets and contents replaced', N'Cabinets to be replaced when they get in this condition', 0, NULL, N'Implementação de 02 pontos de aspersão via bicos spray para incremento da turbulência controlada.
INSERT INTO #PVC VALUES (7330, N'81013737', N'81013737', N'Retorno Demandas Programada', NULL, N'No Replication/Sem replicação', N'A uma grande dificuldade no rastreios das informações das demandas programadas bem como na tratativa de carteira, principalmente nas troca de turno.', N'Rastreio de informações e estabilidade no controle operacional', N'10279', N'01 - Imagens/01 - Antes/7330.jpeg', N'Antes as informações era publicadas no whatsApp (Ferramenta não Oficial) no modo lista sem um modelo de rastreio, gerando perca de informações e dados com impactos no APR das frotas e também na gerencia.', N'01 - Imagens/02 - Depois/7330.jpeg', N'Foi elaborado um relatório no SharePoint que permite ter um acompanhamento por semana, mantendo o histórico anual e facilitando no mapeamento das demandas que ficaram pendentes de baixa, melhorando na visualização e organização das frotas, gerando ganhamos positivos na aderência das programações.', NULL, N'Sim. Com a organização das informações ficou nítida a satisfação das equipes que geram as tratativas das demandas programadas', N'VPS funciona', 0, NULL, N'Deslocamento mais fácil, ergonomicamente mas favorável.  ', '2026-01-02T00:00:00.000', '2026-01-05T15:02:28.000', N'81013737', NULL, 1);
INSERT INTO #PVC VALUES (7331, N'81057208', N'81057208', N'Reforço e Padronização da Base do Compressor de Ar-Condicionado', NULL, N'Others/Outros', N'Compressores de sistemas de ar condicionado sendo apoiados sobre blocos de concreto', N'Reduzir os perigos e garantir a segurança no fluxo de pessoas.', N'10178', N'01 - Imagens/01 - Antes/7331.jpeg', N'Como demonstrado na fotografia, os compressores das máquinas de ar condicionado estavam montados sobre blocos de cimento, o que implica um risco tanto de curto-circuito quanto de entrada de água no sistema.', N'01 - Imagens/02 - Depois/7331.jpeg', N'Após do análise do local e identificar a causa principal do problema, foi criada uma maneira segura e eficaz de resolvê-lo.', NULL, N'A questão foi resolvida de forma segura, reduzindo a possibilidade de um acidente. ', N'Focar em ajustes simples, contínuos e de baixo custo, mas que geram impacto real na eficiência e confiabilidade do equipamento.', 0, NULL, N'Melhoria de processos.', '2025-12-30T00:00:00.000', '2026-01-05T15:54:57.000', N'81057208', NULL, 1);
INSERT INTO #PVC VALUES (7332, N'800303', N'800303', N'Auto Sampler De-activation', NULL, N'Refining/Refino', N'Auto Sampler has been inactive for some time (est 2 years +).  Maintenance Plans were not deactivated and equipment was taking resources in the maintenance scheduling', N'Eliminate waste - scheduling work that doesn''t happen', N'0', N'01 - Imagens/01 - Antes/7332.jpeg', N'Maintenance Plan was not deactivated so resources were being scheduled to perform PMs on the equipment', N'01 - Imagens/02 - Depois/7332.jpeg', N'Maintenance Plan deactivated and Equipment set to Idle, so it can be brought back in the future and plan re-activated if need be.  No more wasted maintenance resources, freeing up time in the schedule for other jobs.', NULL, N'Eliminate Waste in scheduling jobs that don''t get completed', N'Plan review required', 1000, 3, N'meta alcançada com sucesso.', '2026-01-04T00:00:00.000', '2026-01-05T15:56:34.000', N'800303', NULL, 1);
INSERT INTO #PVC VALUES (7333, N'87000312', N'87000381', N'Remodeling dust collecting duct of the WHB', NULL, N'Refining/Refino', N'Defect', N'To improve defect', N'0', N'01 - Imagens/01 - Antes/7333.jpeg', N'After the PMP, dust collecting duct had occurred a lot of strain due to expansion caused by heat. It had a risk of broken the duct.', N'01 - Imagens/02 - Depois/7333.jpeg', N'Installed flexible joint at the duct. The joint absorbed gap of the duct through the year.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset', 0, NULL, N'Preservar a integridade física do cabo e evitar possíveis eventos', '2026-01-05T00:00:00.000', '2026-01-06T07:41:53.000', N'87000312', NULL, 1);
INSERT INTO #PVC VALUES (7334, N'81006571', N'81046951', N'PLATAFORMA TUB RECALQUE DA 2251BP02', NULL, N'Others/Outros', N'O problema era a exposição de pessoas ao trabalho em altura, além do desperdicio de tempo com espera de mão de obra para montagem', N'ELIMINAR TRABALHO EM ALTURA', N'10044', N'01 - Imagens/01 - Antes/7334.jpeg', N'Antes, os colaboradores estavam expostos a riscos significativos de trabalho em altura devido à necessidade de montar andaimes para trocar a tubulação. Isso não apenas aumentava a probabilidade de acidentes graves, como quedas e lesões, mas também gerava ociosidade da mão de obra durante a montagem do andaime, impactando a eficiência e a segurança do processo', N'01 - Imagens/02 - Depois/7334.jpeg', N'Foi desenvolvido um projeto, juntamente com uma Gestão de Mudança (GM), para instalar uma plataforma fixa que permita aos colaboradores realizar a troca das tubulações sem necessidade de trabalho em altura. Essa solução elimina os riscos associados a essa atividade, como quedas, lesões e acidentes graves, aumentando significativamente a segurança e protegendo a integridade física dos colaboradores. Além disso, reduz o estresse e a exposição a condições perigosas, promovendo um ambiente de trabalho mais seguro e saudável.', NULL, N'Sim, nosso objetivo era eliminar andaimes e ele foi elimado', N'Andaimes podem ser eliminados', 0, NULL, N'O kaizen fez com que não perdêssemos tempo editando várias vezes o mesmo arquivo. ', '2026-01-05T00:00:00.000', '2026-01-06T10:41:10.000', N'81006571', NULL, 1);
INSERT INTO #PVC VALUES (7335, N'498359', N'81047016', N'MELHORIA NO ACESSO DA ESCADA 2101TC01', NULL, N'Others/Outros', N'Acesso da escada, da 2101TC01, com corrosão e risco de queda de nível diferente.', N'ELIMINAR RISCO DE QUEDA', N'10044', N'01 - Imagens/01 - Antes/7335.jpeg', N'Acesso da escada, da 2101TC01, com corrosão e risco de queda de nível diferente.', N'01 - Imagens/02 - Depois/7335.jpeg', N'Foi realizada uma solda e troca da viga no acesso da escada, eliminando o risco de queda de nível diferente, retirando o colaborador da linha de fogo.', NULL, N'meta superada porque além de eliminar o risco de queda de nível diferente tiramos o colaborador da linha de fogo.', N'olhar onde pisa, eliminar risco critico da area.', 0, NULL, N'POL CRT''s can now quickly be fully up to date on current targets, making controlling easier and more consistent ', '2026-01-01T00:00:00.000', '2026-01-06T10:54:58.000', N'498359', NULL, 1);
INSERT INTO #PVC VALUES (7336, N'545267', N'545267', N'Dispositivo de travamento de Válvula dardo', NULL, N'No Replication/Sem replicação', N'Drenar um banco inteiro para realizar pequenas intervenções, o que gerava grande desperdício de concentrado e demandava elevado esforço dos colaboradores para executar a drenagem.', N'Reduzir o número de drenagens das CF''s.', N'10054', N'01 - Imagens/01 - Antes/7336.jpeg', N'Antes, era necessário drenar um banco inteiro para realizar pequenas intervenções, o que gerava grande desperdício de concentrado e demandava elevado esforço dos colaboradores para executar a drenagem.
INSERT INTO #PVC VALUES (7337, N'607144', N'607144', N'Critical Hoist Work Tracking Board', NULL, N'Underground/Subterrâneo', N'Critical Hoist work/inspections are tracked in SAP but do not follow the same date tolerances as MOL requirements, and are not visible to others from the department', N'Proper tracking of legislated hoist work', N'10238', N'01 - Imagens/01 - Antes/7337.jpeg', N'No tracking board exists', N'01 - Imagens/02 - Depois/7337.jpeg', N'More accurate and visible tracking of hoist work', NULL, N'Yes.  Board has been implemented', N'N/A', 0, NULL, N'META ATINGIDA', '2026-01-05T00:00:00.000', '2026-01-06T12:11:06.000', N'607144', NULL, 1);
INSERT INTO #PVC VALUES (7338, N'81006571', N'547828', N'PORTÃO BAIA DE CONTAMINADOS ', NULL, N'Others/Outros', N'Quando a baia estava sem o portão não tinhamos controle de quem descartava ', N'Controle de acesso a baia de contaminados ', N'10044', N'01 - Imagens/01 - Antes/7338.jpeg', N'Antes, não tínhamos controle de acesso à baía de contaminados, o que permitia que algumas pessoas descartassem materiais de forma inadequada e sem respeito, comprometendo a segurança e o meio ambiente.', N'01 - Imagens/02 - Depois/7338.jpeg', N'Instalamos um portão fechado com cadeado na baía de contaminados, permitindo um controle rigoroso dos materiais descartados e garantindo que atendam às exigências do IBAMA.', NULL, N'Sim, com o portão coseguimos diminuir os desvios ambientais na area ', N'Precisamos manter o controle de acesso ', 0, NULL, N'As metas estabelecidas foram plenamente atendidas, solucionando o problema inicial e trazendo benefícios adicionais de padronização e confiabilidade ao processo.', '2026-01-05T00:00:00.000', '2026-01-06T12:29:19.000', N'81006571', NULL, 1);
INSERT INTO #PVC VALUES (7339, N'81035407', N'500640', N'SUPORTE PARA BERGS ', NULL, N'No Replication/Sem replicação', N'OS BERGS utilizados para materiais contaminados não tinham bases. ', N'5s e organização ', N'10144', N'01 - Imagens/01 - Antes/7339.jpeg', N'Os bergs usados nos BOX para armazenar materiais contaminados (panos, trapos, mangueiras, etc.) não tinham uma base de sustentação adequada, o que gerava risco de vazamentos e acidentes, além de não atender às normas de segurança e meio ambiente. ', N'01 - Imagens/02 - Depois/7339.jpeg', N'Utilizando materiais que seriam descartados como os "tote bin"  foi confeccionado um suporte adequado para os bergs, garantindo o armazenamento seguro de materiais contaminados com óleo e graxa. A sustentação proporciona estabilidade, evita tombamentos e vazamentos, reduzindo o risco de contaminação do solo e do meio ambiente, além de contribuir para a segurança dos colaboradores que circulam na área, e para o meio ambiente. ', NULL, N'Inicialmente poderia haver contaminações dos matérias contaminados que eram descartados no bergs de todo jeito. ', N'Sustentabilidade ', 0, NULL, N'A pré‑lubrificação elevou a confiabilidade do motor, reduziu o desgaste na partida e contribuiu para maior disponibilidade e vida útil do ativo, melhorando diretamente sua performance operacional.', '2025-12-30T00:00:00.000', '2026-01-06T13:00:33.000', N'81035407', NULL, 1);
INSERT INTO #PVC VALUES (7340, N'81008761', N'536809', N'Melhoria para reutilização de placas desgastadas de revestimento do  Cilindro do Moinho SAG', NULL, N'Others/Outros', N'As placas de revestimento do cilindro do moinho SAG possuem olhais que são utilizados para sua movimentação (retirada/instalação pelo manipulador). Porém, após alguns dias de operação, devido ao contato como minério e bolas  no interior do moinho, esses olhais se desgastam e a sua reinstalação não é possível devido à ausência dos olhais.
INSERT INTO #PVC VALUES (7341, N'81039085', N'81039085', N'FLEXIBILIZAÇÃO DRENAGEM CX-2020-01 - FILTRAGEM ', NULL, N'Others/Outros', N'TRANSBORDO CONSTANTE DA CAIXA CX-2020-01 OCASIONANDO PARADA DOS FILTROS E ACUMULO DE MATERIAL NO SUMP.', N'AUMENTO DA DISPONIBILIDADE OPERACIONAL ', N'10343', N'01 - Imagens/01 - Antes/7341.jpeg', N'Sistema de bombeamento da caixa CX-2020-01, atraves das bombas de Salobo 01 e 02, com linha recalque unificada, ocasionado a disponibilidade de apenas umas das bombas em operação e tambem, constante desgaste pré-maturo de rolamento devido retorno na bomba atraves da linha de recalque unificada.', N'01 - Imagens/02 - Depois/7341.jpeg', N' A solução foi implementada, através individualização das bombas na sua linha de recalque, aumentando a disponibilidade de ativos para drenagem da caixa CX-2020-01 e redução do modo de falha de quebra de bomba por retorno de recalque. ', NULL, N'Sim, problema solucionado com a instalação de válvula na linha de recalque de drenagem da Caixa CX-2020-01', N'Flexibilização de bombas da Caixa CX-2020-01', 0, NULL, N'Não ocorrer mais colisôes.', '2026-01-05T00:00:00.000', '2026-01-06T13:41:12.000', N'81039085', NULL, 1);
INSERT INTO #PVC VALUES (7342, N'81039085', N'532934', N'SUMP FILTRAGEM', NULL, N'Open Pit/Poço aberto', N'SEGMENTAÇÃO DE MATERIAL NO SUMP DA FILTRAGEM.', N'Otimizar sistema de homogeneização do SUMP', N'10343', N'01 - Imagens/01 - Antes/7342.jpeg', N'SEGMENTAÇÃO DE MATERIAL NO SUMP DA FILTRAGEM, DEVIDO TERMOS SOMENTE UMA VALVULA COM BICO PARA OTIMIZAR A HOMOGENEIZAÇÃO DO MATERIAL,  COM ISSO GERANDO SEGMENTAÇÃO DO MATERIAL, PROVOCANDO TRANSBORDO NO SUMP', N'01 - Imagens/02 - Depois/7342.jpeg', N'Implementação de 02 pontos de aspersão via bicos spray para incremento da turbulência controlada.
INSERT INTO #PVC VALUES (7343, N'81035407', N'81006473', N'CARINHO PARA TRANSPOTE DA TORQUEADERA ', NULL, N'No Replication/Sem replicação', N'ferramenta ficava nesse suporte junto com outras, o que dificultava o deslocamento e impactava negativamente o tempo e a eficiência da atividade', N'TEMPO / ORGANIZAÇÃO ', N'10144', N'01 - Imagens/01 - Antes/7343.jpeg', N'A ferramenta ficava nesse suporte junto com outras, o que dificultava o deslocamento e impactava negativamente o tempo e a eficiência da atividade devido ter que deslocar a ferramenta o que desfavorecia a ergonomia.  ', N'01 - Imagens/02 - Depois/7343.jpeg', N'Confeccionado carrinho de transporte e manuseio para ferramenta ( torquedeira pneumática) , assim melhorando o armazenamento e a ergonomia, facilitando e agilizando o transporte para as atividades. ', NULL, N'Inicialmente havia essa dificuldade para locomover está ferramenta. ', N'ergonomia / tempo de atividade ', 0, NULL, N'Aumento da vida útil dos tecidos.', '2025-12-03T00:00:00.000', '2026-01-06T15:10:45.000', N'81035407', NULL, 1);
INSERT INTO #PVC VALUES (7344, N'81048542', N'81048542', N'Carrinho organizador ', NULL, N'Others/Outros', N'Desorganização da área no momento da atividade. ', N'Organização ', N'10139', N'01 - Imagens/01 - Antes/7344.jpeg', N'Foi identificado que durante as atividades de rutina as ferramentas e peças ficavam em lugares inadequados causando atrasos e desvios nas execução das mesmas. ', N'01 - Imagens/02 - Depois/7344.jpeg', N'Foi disponibilizado um carrinho e fabricado umas divisórias para organizar peças e ferramentas que ficavam desorganizadas.  ', NULL, N'Melhoria de processos.', N'Melhoria de processos ', 0, NULL, N'Mangueira mau posicionadas podendo causar danos, com o suporte com canaleta as mangueiras ficam de forma organizado evitando esses danos.  ', '2026-01-02T00:00:00.000', '2026-01-06T16:34:11.000', N'81048542', NULL, 1);
INSERT INTO #PVC VALUES (7345, N'498359', N'81029880', N'5S NA SALA DE LUBRIFICAÇÃO', NULL, N'Others/Outros', N'SALA DE LUBRIFICAÇÃO COM BASTANTE OLEO NO CHÃO, RISCO DE QUEDA DE MESMO NIVEL, MATERIAL ESPALHADO DESORGANIZADO E LIXO.', N'ELIMINAR RESIDUOS OLEO ', N'10044', N'01 - Imagens/01 - Antes/7345.jpeg', N'SALA DE LUBRIFICAÇÃO COM BASTANTE OLEO NO CHÃO, RISCO DE QUEDA DE MESMO NIVEL, MATERIAL ESPALHADO DESORGANIZADO E LIXO.', N'01 - Imagens/02 - Depois/7345.jpeg', N'Foi realizado limpeza e organização na sala de lubrificação SAG. 
INSERT INTO #PVC VALUES (7346, N'81035680', N'524796', N'SUPORTE DE FIXAÇÃO DO CABO DE ALIMENTAÇÃO', NULL, N'Others/Outros', N'Cabo de alimentação passando pelo kambao de forma inadequada, em contato com quinas vivas e sem fixação correta.', N'Retirar o atrito com quinas vivas e também melhorar a condição estrutural do kambao.', N'10295', N'01 - Imagens/01 - Antes/7346.jpeg', N'Cabo de alimentação passando pelo kambao de forma inadequada, em contato com quinas vivas e sem fixação correta. O mesmo estava amarrado com uma corda e a qualquer momento a mesma poderia se romper ocasionando avarias no cabo.', N'01 - Imagens/02 - Depois/7346.jpeg', N'De forma a preservar a integridade física do cabo e evitar possíveis eventos, providenciamos uma abraçadeira para fixar o mesmo no kambao. A mesma tem a base soldada na estrutura e com borrachas que fixam o cabo de alimentação,  assim retiramos o atrito com quinas vivas e também melhoramos a condição estrutural do kambao.', NULL, N'Sim, retiramos o atrito com quinas vivas e também melhoramos a condição estrutural do kambao.', N'Podemos replicar esse kaizen em todas as máquinas ', 0, NULL, N'Além da redução de tempo e eliminação de erros, a melhoria trouxe escalabilidade para novas demandas, padronização dos dados com maior confiabilidade, liberação de mais de 11 dias úteis por rodada para atividades estratégicas e criação de um modelo replicável para outros fluxos, fortalecendo a cultura de inovação e melhoria contínua.', '2026-01-06T00:00:00.000', '2026-01-07T04:50:49.000', N'81035680', NULL, 1);
INSERT INTO #PVC VALUES (7347, N'81047951', N'81047951', N'Etiquetas padronizadas', NULL, N'Others/Outros', N'Ao longo da rotina temos que editar e imprimir algumas etiquetas para utilizar no laboratório. A produção dessas etiquetas gasta bastante tempo, pois sempre temos que ficar criando do zero.', N'Reduzir o tempo gasto para produção de etiquetas', N'10366', N'01 - Imagens/01 - Antes/7347.jpeg', N'Antes era necessário editar um mesmo arquivo, de acordo com nossa necessidade, para gerar nossas etiquetas de rotina, gastando bastante tempo.', N'01 - Imagens/02 - Depois/7347.jpeg', N'Foi criado arquivos prontos com as principais necessidades da rotina, todo os arquivos estão prontos para imprimir, gerando ganho de tempo na rotina.', NULL, N'O problema foi resolvido com a melhoria.', N'A melhoria nos ajudou a ganhar mais tempo na rotina.', 0, NULL, N'Resultado foi excelente', '2026-01-06T00:00:00.000', '2026-01-07T06:31:25.000', N'81047951', NULL, 1);
INSERT INTO #PVC VALUES (7348, N'81005912', N'81005912', N'POL CRT key targets tracker', NULL, N'Refining/Refino', N'There was no single dynamic record of all key targets for POL CRT''s', N'To make it easier to find current important targets needed for running the POL pannel ', N'10272', N'01 - Imagens/01 - Antes/7348.jpeg', N'POL adjust variables to achieve key targets. Targets are updated by tech services & production leads via change emails and other communications. To find the most current targets CRT''s would have to go back through multiple emails from different to find the latest communications.  ', N'01 - Imagens/02 - Depois/7348.jpeg', N'Created a new section in the POL CRT handover that contains the 6 most important Targets. CRT''s can update these numbers as they are instructed. Now there is one central place to find these numbers quickly, while also archiving any changes over time.', NULL, N'CRT''s can now easily see all current key targets, and track how they have changed over time', N'alignment on information sharing leads to better information', 0, NULL, N'Redução de exposição a espaço confinado e carga suspensa.', '2026-01-06T00:00:00.000', '2026-01-07T09:56:43.000', N'81005912', NULL, 1);
INSERT INTO #PVC VALUES (7349, N'81022747', N'81011443', N'Foi realizado melhoria no abastecimento do fluido hidráulico', NULL, N'Others/Outros', N'Antes removia  bujão da parte superior tanque reservatório para completar o nível .
INSERT INTO #PVC VALUES (7350, N'498359', N'472909', N'TROCA DE TUBULAÇÃO DE AR', NULL, N'Others/Outros', N'TUBULAÇÃO DE AR COMPRIMIDO COM VAZAMENTO DEVIDO CORROSÃO, BAIXANDO A PRESSÃO AR COMPRIMIDO DO SISTEMA DE AUTOMAÇÃO.', N'ELIMINAR VAZAMENTO DE AR ', N'10044', N'01 - Imagens/01 - Antes/7350.jpeg', N'TUBULAÇÃO DE AR COMPRIMIDO COM VAZAMENTO DEVIDO CORROSÃO, BAIXANDO A PRESSÃO AR COMPRIMIDO DO SISTEMA DE AUTOMAÇÃO.', N'01 - Imagens/02 - Depois/7350.jpeg', N'fOI CONFECCIONADO UMA TUBULAÇÃO DE MELHOR QUALIDADE, ELIMINANDO O VAZAMENTO E MANTENDO A PRESSÃO ESTAVEL DO EQUIPAMENTO.', NULL, N'META ATINGIDA', N'MELHORA NO PROCESSO', 0, NULL, NULL, '2026-01-01T00:00:00.000', '2026-01-07T14:57:51.000', N'498359', NULL, 1);
INSERT INTO #PVC VALUES (7351, N'81017966', N'81017966', N'INSTALAÇÃO CONTROLE REMOTO TE 2305 SA01', NULL, N'Projects/Projetos', N'A operação com botoeira pendente apresentava riscos à segurança, restrição de mobilidade do operador, desgaste frequente do cabo e menor produtividade, além de problemas ergonômicos e custos recorrentes de manutenção.', N'O objetivo da substituição da botoeira pendente por controle remoto sem fio', N'10124', N'01 - Imagens/01 - Antes/7351.jpeg', N'Antes da implantação do controle remoto, a operação do equipamento era realizada por meio de botoeira pendente com cabo, apresentando as seguintes características:
INSERT INTO #PVC VALUES (7352, N'81018935', N'121343', N'Criação do sistema de pré-lubrificação no motor diesel da frota 854k', NULL, N'Projects/Projetos', N'Problema: Os motores ACERT C32 dos tratores de pneus da frota 854K realizam a partida sem sistema de pré-lubrificação.
INSERT INTO #PVC VALUES (7353, N'521434', N'521434', N'Recondicionamento de óleo isolante com recursos próprios.', NULL, N'Others/Outros', N'Ao ser detectado contaminação no óleo isolante dos transformadores, eram necessário realizar a mobilização de empresa parceira para realizar o tratamento do óleo. Em casos de mobilização para atendimento emergencial poderia demorar até 48h para o inicio do atendimento . A empresa parceira utiliza máquinas de termovácuo para desidratação e desgaseificação do óleo. Porém para essa atividade temos um custo elevado de mobilização de mão de obra e equipamentos, devido a ausência desses recursos no site.', N'Realizar o tratamento do óleo isolante com recursos próprios.', N'10197', N'01 - Imagens/01 - Antes/7353.jpeg', N'Ao ser detectado contaminação no óleo isolante dos transformadores, eram necessário realizar a mobilização de empresa parceira para realizar o tratamento do óleo. Em casos de mobilização para atendimento emergencial poderia demorar até 48h para o inicio do atendimento . A empresa parceira utiliza máquinas de termovácuo para desidratação e desgaseificação do óleo. Porém para essa atividade temos um custo elevado de mobilização de mão de obra e equipamentos, devido a ausência desses recursos no site.', N'01 - Imagens/02 - Depois/7353.jpeg', N'Realizado aquisição de equipamento termovácuo, juntamente com treinamento de capacitação da equipe. Com isso passamos a ter uma equipe especializada em recondicionamento de óleo, podendo agir imediatamente após a detecção de contaminantes (água ou gases) no óleo, sem depender da agenda de terceiros. Evitando o tempo de espera de mobilização de empresas parceiras e reduzindo o custo da atividade.', NULL, N'Sim, com a aquisição do equipamento de termovácuo, aliada ao treinamento de capacitação da equipe, possibilitou a internalização do serviço de recondicionamento de óleo isolante. Com isso, a atuação passou a ser imediata após a identificação de contaminantes, como água ou gases dissolvidos, eliminando a dependência de fornecedores externos. Essa iniciativa resultou na redução dos custos operacionais, ao suprimir despesas com mobilização de empresas terceirizadas, além de minimizar tempos de parada, aumentando a eficiência dos ativos e gerando economia direta para a operação.', N'Otimização de processos', 100000, 1, N'The new lubricator don''t need the weekly attention for plugging up ', '2025-12-12T00:00:00.000', '2026-01-07T16:15:07.000', N'521434', NULL, 1);
INSERT INTO #PVC VALUES (7354, N'81046928', N'81046928', N'Escada de acesso ao eixo', NULL, N'Others/Outros', N'Escada com ângulo de inclinação baixo, sobrepondo sobre local de parada de manutenção do martelo do rompedor, mesmo veio a colidir e danificar a escada.', N'Eliminar interferências', N'0', N'01 - Imagens/01 - Antes/7354.jpeg', N'Escada com ângulo de inclinação baixo, sobrepondo sobre local de parada de manutenção do martelo do rompedor, mesmo veio a colidir e danificar a escada.', N'01 - Imagens/02 - Depois/7354.jpeg', N'Fabricado nova escada com ângulo maior e deixando altura entre local de manutenção do rompedor com mais espaço, evitando batida do martelo contra estrutura da escada.', NULL, N'Solucionado incidência de colisões do rompedor na estrutura da escada.', N'Levar em consideração interferências da área antes de realizar projetos.', 0, NULL, N'Este espaço foi desenvolvido para centralizar, organizar e compartilhar documentos e informações importantes do nosso cotidiano 
INSERT INTO #PVC VALUES (7355, N'983254', N'81052213', N'SUPORTE PARA EIXO DO AGITADOR 2251-AG-01', NULL, N'Others/Outros', N'Exposição de pessoas e tempo nas intervenções no eixo do agitador (2251-AG-01) do tanque 2551TQ10 da filtragem.', N'Redução no tempo da limpeza industrial e intervenção mecânica no eixo do agitador 2251-AG-01', N'10054', N'01 - Imagens/01 - Antes/7355.jpeg', N'Execução de drenagem completa do tanque, utilizando o sump de contenção, o que compromete a eventual drenagem do espessador. A atividade exige ainda o acesso da equipe de limpeza industrial ao interior do tanque para realização da limpeza, com suporte operacional de caminhão‑pipa.', N'01 - Imagens/02 - Depois/7355.jpeg', N'Projeto, desenvolvimento e fabricação de dispositivo para acoplamento ao eixo do agitador 2251‑AG‑01, permitindo o içamento seguro e a realização de intervenções mecânicas, com a eliminação da condição histórica de drenagem e limpeza total do tanque 2551‑TQ‑10 do sistema de filtragem.', NULL, N'Meta superada, tempo de limpeza do ativo foi eliminado na condição proposta para intervenção no agitador 2251‑AG‑01.', N'Redução de riscos', 5000, 1, N'Once the vacuum is set up - the crews will be able to vacuum the fines directly into the bin ', '2025-12-05T00:00:00.000', '2026-01-07T16:47:05.000', N'983254', NULL, 1);
INSERT INTO #PVC VALUES (7356, N'81029883', N'81029883', N'FI-2020SA-31 MANIFOLD', NULL, N'Projects/Projetos', N'Foi analisado essa condição de melhoria, após a operação realizar limpeza nas mangueiras de lavagem do filtro, e sentirem a necessidade de fazer limpeza também na tubulação, para melhorar a qualidade operacional , não obtendo sucesso por ausência de saída.
INSERT INTO #PVC VALUES (7357, N'81048542', N'81048572', N'Suporte com canaleta para mangueira ', NULL, N'Others/Outros', N'Mangueira mau posicionada, podendo causar danos na mangueira.', N'melhoria continua ', N'10139', N'01 - Imagens/01 - Antes/7357.jpeg', N'Mangueira mau posicionada, amarrada com abraçadeiras plásticas e próximo ao chão podendo danificar a mesma.    ', N'01 - Imagens/02 - Depois/7357.jpeg', N'Foi feito um suporte com canaleta e colocada as mangueiras de forma organizada para evitar danos na mesma.', NULL, N'Mangueira mau posicionadas podendo causar danos, com o suporte com canaleta as mangueiras ficam de forma organizado evitando esses danos.  ', N'sentimento de dono , organização. ', 0, NULL, N'Aumento do intervalo de tempo para manutenções preventivas devido equipamento se manter mais livre de material da área.', '2026-01-06T00:00:00.000', '2026-01-07T18:00:11.000', N'81048542', NULL, 1);
INSERT INTO #PVC VALUES (7358, N'1015393', N'1015393', N'Compressor Room Lighting', NULL, N'No Replication/Sem replicação', N'Area behind 221 air compressors is poorly lit making routine maintenance and rounds difficult. Poor lighting also makes walking in the area less safe.', N'Lighting Improvement', N'0', N'01 - Imagens/01 - Antes/7358.jpeg', N'Dark area along entire north side of 221 air compressors as no lighting exists here.', N'01 - Imagens/02 - Depois/7358.jpeg', N'Lighting installed along northern side of compressors. Work area is now well illuminated for maintenance activities and operator rounds.', NULL, N'Yes, area is now well lit.', N'Safety', 0, NULL, N'The addition of interlock/alarm for power and free motor current should help prevent further dropped mandrels.', '2026-01-07T00:00:00.000', '2026-01-08T03:25:15.000', N'1015393', NULL, 1);
INSERT INTO #PVC VALUES (7359, N'516091', N'81054395', N'Automação Inteligente para Gestão de Materiais', NULL, N'Open Pit/Poço aberto', N'Durante o processo de codificação de materiais junto à CH Master, foi identificado um gargalo operacional: cada part number retornava por e-mail individual, exigindo leitura, localização na base e transcrição manual do código Vale. Para uma base com 2.800 PNs, isso representava cerca de 93 horas de trabalho, tornando o processo lento, suscetível a erros e sem escalabilidade, já que novas demandas continuam surgindo. Essa situação foi detectada ao analisar o fluxo de retorno das codificações e perceber que o método manual não atendia às necessidades de agilidade e confiabilidade exigidas pelo negócio.', N'Automatizar a consolidação da codificação de materiais, reduzindo o tempo de execução em mais de 99% e garantindo escalabilidade para futuras demanda', N'10023', N'01 - Imagens/01 - Antes/7359.jpeg', N'Durante o processo de codificação de materiais junto à CH Master, foi identificado um gargalo operacional: cada part number e Código material retornava por e-mail individual, exigindo leitura, localização na base e transcrição manual do código Vale. Para uma base com 2.800 PNs, isso representava cerca de 93 horas de trabalho, tornando o processo lento, suscetível a erros e sem escalabilidade, já que novas demandas continuam surgindo. Essa situação foi detectada ao analisar o fluxo de retorno das codificações e perceber que o método manual não atendia às necessidades de agilidade e confiabilidade exigidas pelo negócio. ', N'01 - Imagens/02 - Depois/7359.jpeg', N'Solução/Melhoria
INSERT INTO #PVC VALUES (7360, N'81006571', N'81046970', N'PASSARELA EM FRENTE AO SAG', NULL, N'Others/Outros', N'Habvia uma passarela de passagem de pessoas feitas com andaime ', N'Eliminar passarela de andaime', N'10044', N'01 - Imagens/01 - Antes/7360.jpeg', N'Antes, tínhamos uma passarela de trânsito de pessoas feita de andaime, que gerava poluição visual, impactando negativamente a estética do ambiente de trabalho. Além disso, expunha os usuários a riscos de acidentes e quedas, comprometendo a segurança e o bem-estar dos colaboradores. Com isso, o local se tornava menos organizado e mais propício a incidentes.', N'01 - Imagens/02 - Depois/7360.jpeg', N'Com a implementação da passarela fixa, melhoramos as condições de trabalho, eliminamos a poluição visual e, principalmente, removemos o risco de pessoas transitarem sob a plataforma de andaime, aumentando significativamente a segurança no local.', NULL, N'Conseguimos eliminar uso de andaime', N'Eliminar andaimes é necessario', 0, NULL, N'Implementar um processo sistemático de acompanhamento das perdas precoces de componentes, com envolvimento ativo da equipe de confiabilidade, visando identificar causas raiz, propor ações corretivas e prevenir recorrências.', '2026-01-06T00:00:00.000', '2026-01-08T10:46:31.000', N'81006571', NULL, 1);
INSERT INTO #PVC VALUES (7361, N'493280', N'92000248', N'Dispositivo de travamento do eixo do 2551-AG-10', NULL, N'Others/Outros', N'Exposição de colaboradores e processos excessivos. 
INSERT INTO #PVC VALUES (7362, N'81037096', N'81013737', N'EXTRATIFICAÇÃO PROGRAMAÇÃO SEMANAL', NULL, N'No Replication/Sem replicação', N'BAIXA EFICÁCIA DO ANTIGO RELATÓRIO', N'GARANTIR MAIOR EFICIÊNCIA NO REPORTE DAS ORDENS PROGRAMADAS EM RELATÓRIO', N'10144', N'01 - Imagens/01 - Antes/7362.jpeg', N'O processo de reporte era realizado por meio de um grupo no WhatsApp, sem padronização entre as equipes, resultando em inconsistências nos registros e divergências nos dados reportados, o que comprometia a integridade das informações e impactava negativamente os indicadores de desempenho.', N'01 - Imagens/02 - Depois/7362.jpeg', N'Foi criada uma equipe no Microsoft Teams para centralizar a comunicação e implementado um modelo padronizado de relatório para o registro das ordens programadas. A responsabilidade pelo preenchimento das informações referentes às ordens foi atribuída aos pontos focais de cada turno. O programador realiza a atualização do relatório semanalmente, garantindo a consolidação dos dados e a manutenção do histórico por período, permitindo rastreabilidade e análise de desempenho.', NULL, N'ALCANCE DO OBJETIVO DE UM REPORTE ORGANIZADO E PADRONIZADO QUE TRAGA MAIS EFICIÊNCIA AO PROCESSO', N'EXTRATIFICAÇÃO PADRONIZADA', 0, NULL, N'Redução de posturas inadequadas, maior conforto ao operador, melhoria na ergonomia, aumento da segurança e facilidade no acionamento da bomba e dos aspersores, contribuindo para uma operação mais eficiente e segura.', '2026-01-01T00:00:00.000', '2026-01-08T11:10:28.000', N'81037096', NULL, 1);
INSERT INTO #PVC VALUES (7363, N'81033358', N'81033358', N'Install racking for Equipment Window Storage', NULL, N'Underground/Subterrâneo', N'Prior storage area for equipment windows was too small, which caused stock to be unorganized and area congestion that sometimes resulted in damaged windows.', N'Inventory awareness and organization', N'10238', N'01 - Imagens/01 - Antes/7363.jpeg', N'Prior storage area for equipment windows was too small, which caused stock to be unorganized and area congestion that sometimes resulted in damaged windows.', N'01 - Imagens/02 - Depois/7363.jpeg', N'New storage racking for equipment windows allows for more storage space and better presentation of inventory. This makes stocked items easier to find and manage. Reducing costs spent on unnecessary window purchases and on damaged stock replacement.', NULL, N'Window storage issue was solved by introducing a better means of storing.', N'Proper storage causes savings on inventory', 40000, 3, N'Acompanhamento dos principais modos de falhas para cada frota trimestralmente. ', '2026-01-07T00:00:00.000', '2026-01-08T11:34:02.000', N'81033358', NULL, 1);
INSERT INTO #PVC VALUES (7365, N'514353', N'81045351', N'Quadro de visibilidade de indicadores', NULL, N'Others/Outros', N'Definir e acompanhar simultaneamente diversos indicadores para garantir uma análise completa e eficaz.', N'Acompanhar os indicadores de alimentação e deixo de forma mais visual.', N'10017', N'01 - Imagens/01 - Antes/7365.jpeg', N'Não tinha acompanhamento.', N'01 - Imagens/02 - Depois/7365.jpeg', N'1. Maior Visibilidade e Transparência
INSERT INTO #PVC VALUES (7366, N'81016492', N'81016492', N': Conecta 02: Monitoramento sistema centralizado de lubrificação ', NULL, N'Others/Outros', N'Ausência de monitoramento sistemático das propulsoras por técnicas de análise de condição (vibração e temperatura), aliada à dependência exclusiva de inspeção visual via visor externo, especialmente em cenários de alta severidade operacional.
INSERT INTO #PVC VALUES (7367, N'609694', N'609694', N'Load out lubricator', NULL, N'Underground/Subterrâneo', N'The old lubricators require a lot of maintenance , they are breaking down a lot', N'cut down the maintenance ', N'10238', N'01 - Imagens/01 - Antes/7367.jpeg', N'before - old orange lubricators would always plug up', N'01 - Imagens/02 - Depois/7367.jpeg', N'the new lubricators require less maintenance 
INSERT INTO #PVC VALUES (7368, N'81055557', N'494528', N'Sharepoint Turma CVU', NULL, N'Others/Outros', N'Dificuldade de documentação para acesso rápido visível, para todos da turma .', N'Este espaço foi desenvolvido para centralizar, organizar e compartilhar documentos e informações importantes do nosso dia a dia, como: 	•	Checklists de Inspeções Operacionais 	•	ART 	•	PRO de Operações 	•	RAC e demais documentos atualizados ', N'10229', N'01 - Imagens/01 - Antes/7368.jpeg', N'Dificuldade de documentação para acesso rápido visível, para todos da turma .', N'01 - Imagens/02 - Depois/7368.jpeg', N'SharePoint oficial da Turma CVU – Operação de Usina.
INSERT INTO #PVC VALUES (7369, N'609694', N'609694', N'Install 3090 vacuum to reduce head end cleaning and MSD', NULL, N'Underground/Subterrâneo', N'the vacuum has been on sight for years with no action taken to set it up', N'reduce/eliminate MSD and reduce cleaning time', N'10238', N'01 - Imagens/01 - Antes/7369.jpeg', N'the vacuum was sitting in the surface tent for years, cleaning the head end can take too long and can cause MSDs', N'01 - Imagens/02 - Depois/7369.jpeg', N'The vacuum set up has started - Electrical  confirmed we do have the correct rotation.
INSERT INTO #PVC VALUES (7370, N'609694', N'609694', N'cage door handle redesign', NULL, N'Underground/Subterrâneo', N'If the cage door handle is not put into the down position it will hit the shaft furnishings and be broken', N'reduce damage to cage door handle', N'10238', N'01 - Imagens/01 - Antes/7370.jpeg', N'the cage door handle is just too long and if it is not in the down position it will get broken', N'01 - Imagens/02 - Depois/7370.jpeg', N'A new version of the cage door handle was built - installed . ', NULL, N'After several attempts in making a new handle - the outcome was always similar - the handle was toolong ', N'We have great people that are continuously trying to improve there craft  ', 0, NULL, N'Redução das paradas inesperadas relacionadas a substituição dos freios traseiros.', '2025-12-29T00:00:00.000', '2026-01-08T14:13:56.000', N'609694', NULL, 1);
INSERT INTO #PVC VALUES (7371, N'81046928', N'81046928', N'Proteção contra  queda de material freio retorno  TCLD', NULL, N'Others/Outros', N'Material da correia transportadora caindo sobre disco e freio ocasionando contaminação no sistema do freio.', N'melhoria na manutenção', N'0', N'01 - Imagens/01 - Antes/7371.jpeg', N'Material da correia transportadora caindo sobre disco e sistema de freio ocasionando contaminação e deteriorização no mesmo.', N'01 - Imagens/02 - Depois/7371.jpeg', N'Implementado chapa para excluir a queda de material sobre o sistema de frenagem de retorno da correia transportadora.', NULL, N'Resolvido a queda de material sobre o sistema de freio com o recurso utilizado.', N'Observar ação das interpéries sobre os equipamentos na nossa área que possam agravar mais  a degradação dos equipamentos', 0, NULL, N'Plano sistemático reativado para garantir qualidade da diálise do óleo hidráulico', '2026-01-07T00:00:00.000', '2026-01-08T15:04:18.000', N'81046928', NULL, 1);
INSERT INTO #PVC VALUES (7372, N'81046830', N'1010414', N'System 100 P&F Dropped Mandrel Prevention', NULL, N'Refining/Refino', N'System 100 Power and Free prone to dropping mandrels as it passed by transfer device 6.', N'Prevent mandrels from dropping off the power and free', N'10006', N'01 - Imagens/01 - Antes/7372.jpeg', N'Electrical junction box mounted on transfer device 6 in path of mandrel traveling on power and free. If mandrel swinging on carrier, it could hook edge of junction box and potentially fall off the power and free.', N'01 - Imagens/02 - Depois/7372.jpeg', N'Junction box moved further south on transfer device 6 to prevent collision. An overcurrent alarm/interlock added to power and free motor in case of further collisions. Visible indication added to system 100 control room HMI to inspect power and free if current increases.', NULL, N'Yes, moving the junction box will prevent mandrel from having a collision at ETD6 and the added logic should prevent further dropping of mandrels.', N'Be mindful of mandrel pathing and potential issues to drop mandrels from carriers', 0, NULL, N'Saúde e segurança', '2026-01-07T00:00:00.000', '2026-01-08T16:00:05.000', N'81046830', NULL, 1);
INSERT INTO #PVC VALUES (7373, N'81020596', N'520164', N'REPOSICIONAMENTO E MELHORIANA FIXAÇÃO DO MONITOR DAS CAMERAS. ', NULL, N'Others/Outros', N'Antes, o monitor das câmeras estava instalado em um suporte que, com o tempo e a depreciação, apresentou folga na fixação, fazendo com que o monitor ficasse solto. Essa condição comprometia a visibilidade das imagens, a ergonomia do operador e aumentava o risco de distrações durante a operação do equipamento.', N'GARANTIR FIXAÇÃO ADEQUADA E ELIMINAR FOLGAS.', N'10140', N'01 - Imagens/01 - Antes/7373.jpeg', N'Antes, o monitor das câmeras estava instalado em um suporte que, com o tempo e a depreciação, apresentou folga na fixação, fazendo com que o monitor ficasse solto. Essa condição comprometia a visibilidade das imagens, a ergonomia do operador e aumentava o risco de distrações durante a operação do equipamento.', N'01 - Imagens/02 - Depois/7373.jpeg', N'Instalação de suporte adequado e fixação correta do monitor, garantindo melhor ergonomia, estabilidade do equipamento e visibilidade das imagens, reduzindo riscos de distração durante a operação.', NULL, N'Sim, a instalação do novo suporte eliminou a folga do monitor, garantindo a fixação adequada e atendendo à necessidade de segurança e ergonomia.', N'A importância de realizar inspeções periódicas nos suportes e garantir a instalação adequada para manter a ergonomia e a segurança operacional.', 0, NULL, N'Easier to distribute mail and notifications.  Contacts are up to date and organized.', '2026-01-07T00:00:00.000', '2026-01-09T09:11:13.000', N'81020596', NULL, 1);
INSERT INTO #PVC VALUES (7374, N'81042135', N'81042135', N'Gestão de componentes', NULL, N'Others/Outros', N'PCM realiza o acompanhamento das perdas de componentes que não atingiram a vida útil estimada.', N'Acompanhamento dos componentes com perda precoce por frota', N'10015', N'01 - Imagens/01 - Antes/7374.jpeg', N'PCM realiza o acompanhamento das perdas de componentes que não atingiram a vida útil estimada.', N'01 - Imagens/02 - Depois/7374.jpeg', N'Criado material para acompanhamento dos componentes que tiveram perdas antes da vida útil estimada pelo fornecedor, com isso direcionamos as análises para equipe de gestão de componentes ou para os engenheiros das frotas.', NULL, N'Em acompanhamento', N'Acompanhamento das perdas precoces em componentes por frota', 0, NULL, NULL, '2025-10-01T00:00:00.000', '2026-01-09T09:28:44.000', N'81042135', NULL, 1);
INSERT INTO #PVC VALUES (7375, N'81042135', N'81042135', N'Gestão de MCS em reuniões de FMDS/RP', NULL, N'No Replication/Sem replicação', N'Ausência de um processo estruturado para monitoramento e resposta aos gatilhos de MCS pela equipe de execução.', N'Acompanhar execução de MCS em reuniões de FMDS/Rp', N'10015', N'01 - Imagens/01 - Antes/7375.jpeg', N'Ausência de um processo estruturado para monitoramento e resposta aos gatilhos de MCS pela equipe de execução.', N'01 - Imagens/02 - Depois/7375.jpeg', N'Criado material estruturado para monitoramento e resposta aos gatilhos de MCS pela equipe de execução.', NULL, N'Monitoramento efetivo da execução dos gatilhos de MCS pela equipe de execução.', N'Monitoramento efetivo da execução dos gatilhos de MCS pela equipe de execução.', 0, NULL, N'AÇÃO, POIS DEMOSTRA NOSSA A ROTINAS.', '2025-10-08T00:00:00.000', '2026-01-09T09:35:36.000', N'81042135', NULL, 1);
INSERT INTO #PVC VALUES (7376, N'81020596', N'81049665', N'MELHORIA ERGONOMICA NO PAINEL DE CONTROLE DO MEGA TANQUE DO CAMINHAÃO PIPA.', NULL, N'Others/Outros', N' Painel de funcionamento do controle do mega tangue do pipa CA 11
INSERT INTO #PVC VALUES (7377, N'81042135', N'81042135', N'Indicador TRF - Taxa de redução de falhas frotas ', NULL, N'No Replication/Sem replicação', N'Não existia uma sistemática para acompanhamento de redução dos modos de falhas das frotas.', N'Redução de 40% do principal modo de falha nas frotas', N'10015', N'01 - Imagens/01 - Antes/7377.jpeg', N'Não existia uma sistemática para acompanhamento de redução dos modos de falhas das frotas.', N'01 - Imagens/02 - Depois/7377.jpeg', N'O indicador de Taxa de Redução de Falhas (TRF) tem como objetivo principal medir o progresso na diminuição da ocorrência de falhas nos ativos ao longo de um período específico, refletindo o impacto das ações de confiabilidade e melhoria contínua. Ele serve como uma ferramenta estratégica para: Monitorar a eficácia das intervenções, direcionar prioridades, estabelecer metas tangíveis e validade iniciativas de melhoria.', NULL, N'com a aplicação do indicador, conseguimos acompanhar evolução dos principais modos de falhas para cada frota e assim direcionar os trabalhos.', N'Acompanhamento trimestral de redução dos modos de falhas das frotas', 0, NULL, NULL, '2025-10-01T00:00:00.000', '2026-01-09T09:43:12.000', N'81042135', NULL, 1);
INSERT INTO #PVC VALUES (7378, N'81042135', N'81042135', N'Indíce de eficiência análise de falhas - IE RAF', NULL, N'Others/Outros', N'Sem acompanhamento do indicador de índice de eficiência de análise de falhas - IE RAF.', N'medir a eficácia das ações resultantes das análises de falha em combater a reincidência de falhas em um determinado período amostral', N'10015', N'01 - Imagens/01 - Antes/7378.jpeg', N'Sem acompanhamento do indicador de índice de eficiência de análise de falhas - IE RAF.', N'01 - Imagens/02 - Depois/7378.jpeg', N'O indicador tem como objetivo medir a eficácia das ações resultantes das análises de falha em combater a reincidência de falhas em um determinado período amostral: Monitorar a eficácia das RAfs/acompanhamento falhas críticas alto tempo duração.', NULL, N'acompanhamento trimestral para as frotas.', N'Acompanhar a eficiência de análise de falhas - IE RAF', 0, NULL, N'padronização e 5S.', '2025-10-01T00:00:00.000', '2026-01-09T09:52:02.000', N'81042135', NULL, 1);
INSERT INTO #PVC VALUES (7379, N'81042135', N'81042135', N'Painel de indicadores - Análise FMDS', NULL, N'Others/Outros', N'No novo painel de indicadores para a FMDS, fazíamos o preenchimento e a colocação das cores com as métricas que até 5% fora da meta orçada ficaria amarelo (alerta) de forma manual. Perdemos muito tempo nesse preenchimento.', N'a priorização mais rápida e de fácil entendimento.', N'10015', N'01 - Imagens/01 - Antes/7379.jpeg', N'No novo painel de indicadores para a FMDS, fazíamos o preenchimento e a colocação das cores com as métricas que até 5% fora da meta orçada ficaria amarelo (alerta) de forma manual. Perdemos muito tempo nesse preenchimento.', N'01 - Imagens/02 - Depois/7379.jpeg', N'Na nova versão, automatizei o painel, agora só basta copiar e colar a base conforme despacho, classificar as datas para cada semana e rodar a macro no botão "Formatação", automaticamente todos os valores e as cores serão preenchidas.', NULL, N'a priorização se torna mais rápida e de fácil entendimento.', N'Com o preenchimento automático, a priorização se torna mais rápida', 0, NULL, N'ESCADA DE ACESSO PLATAFORMA NOS TROUXE TRANQUILIDADE E FACILIDADE NO ACESSO DESTE LOCAL.', '2025-01-01T00:00:00.000', '2026-01-09T09:59:59.000', N'81042135', NULL, 1);
INSERT INTO #PVC VALUES (7380, N'81020596', N'81049665', N'Proteção da câmera de ré do caminhão pipa', NULL, N'Others/Outros', N'A câmera de ré do caminhão pipa ficava exposta à água por não possuir proteção adequada, causando danos frequentes, falhas no funcionamento e comprometendo a segurança durante as manobras.', N'Proteger a câmera de ré contra exposição à água, aumentando sua durabilidade, confiabilidade e garantindo a segurança nas manobras do caminhão pipa.', N'10140', N'01 - Imagens/01 - Antes/7380.jpeg', N'A câmera de ré do caminhão pipa não possuía proteção, ficando diretamente exposta à água, o que ocasionava danos frequentes, falhas no funcionamento e risco à segurança durante as manobras.', N'01 - Imagens/02 - Depois/7380.jpeg', N'Foi confeccionado um suporte de proteção para a câmera de ré, reduzindo a exposição à água e protegendo o equipamento contra danos.', NULL, N'Sim.
INSERT INTO #PVC VALUES (7381, N'187864', N'187864', N'LISTA DE PEÇAS SOBRESSALENTES (BOM) PARA AS SUBESTAÇÕES ELÉTRICAS DO BOMBEAMENTO DA CAVA', NULL, N'Projects/Projetos', N'subestações elétricas para o bombeamento de cava não vieram com as peças sobressalentes. ', N'DISPONIBILIZAR INTENS ESSENCIAS PARA A CONTINUIDADE DA OPERAÇÃO DO SISTEMA ELÉTRICO BOMBEAMENTO DA CAVA', N'10015', N'01 - Imagens/01 - Antes/7381.jpeg', N'Foram adquiridas novas subestações elétricas para o bombeamento de cava, porém as mesmas não vieram com as peças sobressalentes. ', N'01 - Imagens/02 - Depois/7381.jpeg', N'Foi necessário analisar o projeto e gerar uma lista de componentes sobressalentes que atenderiam a pelo menos 2 anos de operação.', NULL, N'Problema resolvido (falta da lista de peças sobressalentes)', N'ADQUIRIR NOVAS SUBESTAÇÃO COM A INCLUSÃO DE PEÇAS SOBRESSALENTES', 0, NULL, N'SEGURANÇA E PRODUTIVIDADE', '2025-04-25T00:00:00.000', '2026-01-09T10:05:48.000', N'187864', NULL, 1);
INSERT INTO #PVC VALUES (7382, N'81016005', N'81016005', N'Melhoria do sensor da trava do Strut Sandvik DR416i', NULL, N'Others/Outros', N'O posicionamento do sensor responsável pela leitura do recolhimento da trava do Strut na perfuratriz Sandvik DR416i pode gerar leituras incorretas e causar empeno do tirante (Strut), evidenciando uma falha de projeto.', N'Evitar perda financeira e indisponibilidade do ativo', N'10015', N'01 - Imagens/01 - Antes/7382.jpeg', N'O posicionamento do sensor responsável pela leitura do recolhimento da trava do Strut na perfuratriz Sandvik DR416i pode gerar leituras incorretas e causar empeno do tirante (Strut), evidenciando uma falha de projeto.', N'01 - Imagens/02 - Depois/7382.jpeg', N'Realizada solicitação ao fabricante de melhoria para o sistema de travamento de Strut (tirante) do mastro, para que ocorresse o travamento efetivo, sem possibilidade de atraso na atuação e empeno do Strut (tirante). Melhoria realizada através do Boletim  B000924 da fábrica Sandvik através da solicitação de melhoria partida da Engenharia de Confiabilidade de Salobo Metais.', NULL, N'Problema resolvido em virtude de evitar empeno do Strut por falha de projeto', N'Segurança em primeiro lugar', 0, NULL, N'melhoria, organização e bem-estar', '2025-02-02T00:00:00.000', '2026-01-09T10:15:21.000', N'81016005', NULL, 1);
INSERT INTO #PVC VALUES (7383, N'1016070', N'1016070', N'Desenvolvimento de ferramenta para medição dos freios traseiros da frota 797F', NULL, N'Others/Outros', N'Não realizada medição do % de desgaste dos freios traseiros devido: 1) ausência de ferramenta para a execução da atividade; 2) treinamento das equipes de manutenção preventiva na execução da atividade.', N'Realizar medição dos freios traseiros da frota 797F', N'10015', N'01 - Imagens/01 - Antes/7383.jpeg', N'Não realizada medição do % de desgaste dos freios traseiros devido: 1) ausência de ferramenta para a execução da atividade; 2) treinamento das equipes de manutenção preventiva na execução da atividade.', N'01 - Imagens/02 - Depois/7383.jpeg', N'Com o desenvolvimento/ aquisição da ferramenta de medição dos freios traseiros e treinamento da equipe de manutenção preventiva se fez possível a medição do % dos freios traseiros da frota 797F. Desta forma é possível ter previsibilidade da condição dos freios e substituí-los no tempo correto e de forma planejada. Observação: atividade inserida no plano de manutenção preventiva.', NULL, N'Com a medição dos freios traseiros de forma sistemática se fez possível a substituição dos freios de forma planejada e assertiva. ', N'Maior previsibilidade na substituição dos freios traseiros.', 0, NULL, N'Ganho na produção da Filtragem com a disponibilidade de ativos. ', '2025-09-12T00:00:00.000', '2026-01-09T10:21:55.000', N'1016070', NULL, 1);
INSERT INTO #PVC VALUES (7384, N'81016005', N'81016005', N'Melhoria no processo de diálise do sistema hidráulico da frota de perfuratrizes Epiroc Flexiroc D65', NULL, N'Others/Outros', N'a diálise era realizada de forma invasiva no sistema hidráulico, exigindo a abertura das tampas e a inserção de mangueiras diretamente no óleo, o que aumentava o risco de contaminação por agentes externos.', N'Padronizar processo de diálise do óleo hidráulico para garantir efetividade da limpeza', N'10015', N'01 - Imagens/01 - Antes/7384.jpeg', N'a diálise era realizada de forma invasiva no sistema hidráulico, exigindo a abertura das tampas e a inserção de mangueiras diretamente no óleo, o que aumentava o risco de contaminação por agentes externos.', N'01 - Imagens/02 - Depois/7384.jpeg', N'Foram instalados engates rápidos e pontos de circulação para permitir a conexão externa das mangueiras, evitando a abertura invasiva do sistema hidráulico e sua exposição a agentes externos, assegurando a qualidade do processo de diálise do óleo. Plano sistemático reativado para garantir qualidade da diálise do óleo hidráulico', NULL, N'Melhora no processo de diálise do sistema hidráulico da frota Epiroc D65', N'Plano sistemático reativado para garantir qualidade da diálise do óleo hidráulico', 0, NULL, N'Implementação de 02 pontos de aspersão via bicos spray, para incrementar na tubulação.
INSERT INTO #PVC VALUES (7385, N'92000528', N'516646', N'CRIAÇÃO DE ART PARA DESCARTE DE PNEUS DA FROTA DE EQUIPAMENTOS LEVES', NULL, N'Others/Outros', N'Não havia uma ART para execução da atividade de descarte de pneus para a frota de equipamentos leves do Salobo.', N'Elaborar análise do risco da tarefa para descarte de pneus da frota de equipamentos leves', N'10015', N'01 - Imagens/01 - Antes/7385.jpeg', N'Não havia uma ART para execução da atividade de descarte de pneus para a frota de equipamentos leves do Salobo.', N'01 - Imagens/02 - Depois/7385.jpeg', N'Foi elaborada e cadastrada ART para atividade de descarte de pneus da frota de equipamentos leves do Salobo.', NULL, N'Não existia esta ART para a atividade de descarte de pneus para a frota de leves do Salobo, por isso foi criada e posteriormente validada pelo time da segurança do trabalho.', N'Melhoria na segurança da atividade', 0, NULL, NULL, '2025-07-30T00:00:00.000', '2026-01-09T10:32:58.000', N'92000528', NULL, 1);
INSERT INTO #PVC VALUES (7386, N'81045764', N'81045764', N'Mail Room', NULL, N'Others/Outros', N'Organized Mail area for a neater and more efficient mail room', N'Organization', N'10255', N'01 - Imagens/01 - Antes/7386.jpeg', N'Disorganized and out dated Mail area.', N'01 - Imagens/02 - Depois/7386.jpeg', N'Organized and up to date with department leads and reports.', NULL, N'Area is neatly organized saving time when distributing mail and important information. ', N'Organized', 0, NULL, N'Alcançamos ótimos resultados de redução de horas para fazer identificar problemas e realizar manutenção na tubulação.', '2026-01-08T00:00:00.000', '2026-01-09T13:27:30.000', N'81045764', NULL, 1);
INSERT INTO #PVC VALUES (7387, N'200795', N'607697', N'Garson Loadout Doors', NULL, N'Others/Outros', N'Ore spillage and water at the loadout would freeze to the ground.  Clean up would require a 3rd party contractor to breakup the frozen material at a cost.  Also cold air from the outdoors would freeze water lines in the headframe and affect the working conditions of the loadout conveyor operator. ', N'Cost reduction and working conditions improvement', N'10238', N'01 - Imagens/01 - Antes/7387.jpeg', N'Ore spillage and water at the loadout would freeze to the ground.  Clean up would require a 3rd party contractor to break up the frozen material at a cost.  Also, cold air from the outdoors would freeze water lines in the headframe and affect the working conditions of the loadout conveyor operator. ', N'01 - Imagens/02 - Depois/7387.jpeg', N'Designed and installed loadout doors.  These doors stretch across the north side of the headframe, behind #3 and #4 compartments. Their purpose is to keep the winter elements from entering the headframe. They are insulated to help retain heat.  Ore spillage can be easily cleaned without freezing.  Improved working conditions for the loadout conveyor operator as cold wind no longer gusts into the area.', NULL, N'Problem solved', N'Cost reduction', 10000, 3, N'Safety', '2025-12-31T00:00:00.000', '2026-01-09T14:59:20.000', N'200795', NULL, 1);
INSERT INTO #PVC VALUES (7388, N'81034166', N'81051248', N'MANGUEIRA PARA DRENAR LÍQUIDO ARREFECEDOR', NULL, N'No Replication/Sem replicação', N'USAMOS UM TOT-BIN CORTADO PARA DRENAR O LÍQUIDO ARREFCEDOR, DE MANEIRA QUE ACABAVA  DERRAMANDO ATE FECHAR O SEU REGISTRO.', N'PADRONIZAÇÃO/ MELHORIA COTINUA', N'10140', N'01 - Imagens/01 - Antes/7388.jpeg', N'ANTIGAMENTE ERA POSTO TOT-BIN PARA DRENAR LIQUIDO ARREFECEDOR, COM POSSIBILIDADES DE DERRAMAR.', N'01 - Imagens/02 - Depois/7388.jpeg', N'POSTO UMA MANGUEIRA E UM REGISTRO PARA FACILITAR O DRENO DO LÍQUIDO ARREFECEDOR, FACILINTANDO A DRENAGEM DO LÍQUIDO ARREFECEDOR', NULL, N'MELHORANDO A ERGONOMIA QUE ANTES ERA DE DIFICIL ACESSO PARA PODER DRENAR.', N'MANTER SEMPRE UMA BOA ROTINA ', 0, NULL, NULL, '2026-01-08T00:00:00.000', '2026-01-09T15:17:28.000', N'81034166', NULL, 1);
INSERT INTO #PVC VALUES (7389, N'81045351', N'81045351', N'QR CODE PRO TERCEIROS', NULL, N'Others/Outros', N'O aumento da demanda de treinamentos de fornecedores evidenciou falhas no controle e na rastreabilidade do cumprimento do PRO-025917, com processos manuais e pouca eficiência na verificação em tempo real, elevando o risco de acesso de fornecedores sem treinamento válido e impactos na segurança e organização do site de Salobo.', N'Assegurar o cumprimento do PRO-025917, fortalecendo a conformidade com os requisitos de SSMA e diretrizes da Vale.', N'10017', N'01 - Imagens/01 - Antes/7389.jpeg', N'O acompanhamento era manual.', N'01 - Imagens/02 - Depois/7389.jpeg', N'A placa do QR CODE está instalada na área externa das docas, para facilitar o acompanhamento dos treinamentos do PRO de forma mais precisa e tecnológica. O QR Code direciona para um formulário com checklist de inspeção do veículo e dados do motorista e da empresa, garantindo um trânsito mais seguro e organizado dentro do site.', NULL, N'A padronização do checklist de inspeção de veículos e dados do motorista contribuiu para maior organização e controle do fluxo interno.', N'O uso de QR Code facilitou o acompanhamento dos treinamentos e aumentou a rastreabilidade das informações de forma prática e segura.', 0, NULL, N'Todos os componentes devem estar identificados com tags legíveis, bem posicionadas e resistentes, garantindo fácil visualização e clareza para qualquer colaborador. Essa prática assegura:
INSERT INTO #PVC VALUES (7390, N'81046149', N'81040359', N'Mirante  Panorâmico  Britagem ', NULL, N'No Replication/Sem replicação', N'Durante as paradas de britagem temos um fluxo grande de pessoas no piso superior da britagem, o que acaba gerando exposição para essas pessoas que não estão envolvidas diretamente nas atividades. Muito dessas atividades é trabalho a quente onde tem projeção de fagulhas, içamento de cargas. montagem de andaime, todas as atividades geram risco para as pessoas que não estão ligadas diretamente e não fizeram parte da analise de risco da tarefa pois ficam transitando em torno da área, ai precisamos ficar parando as atividades para não expor pessoas. O que gera muito atraso nas entregas, pois precisamos ta parando constante para realizar isolamento, ficar autorizando a entrada e saída de pessoas.', N'Mirante ', N'10044', N'01 - Imagens/01 - Antes/7390.jpeg', N'Durante as paradas de britagem temos um fluxo grande de pessoas no piso superior da britagem, o que acaba gerando exposição para essas pessoas que não estão envolvidas diretamente nas atividades. Muito dessas atividades é trabalho a quente onde tem projeção de fagulhas, içamento de cargas. montagem de andaime, todas as atividades geram risco para as pessoas que não estão ligadas diretamente e não fizeram parte da analise de risco da tarefa pois ficam transitando em torno da área, ai precisamos ficar parando as atividades para não expor pessoas. O que gera muito atraso nas entregas, pois precisamos ta parando constante para realizar isolamento, ficar autorizando a entrada e saída de pessoas.', N'01 - Imagens/02 - Depois/7390.jpeg', N'com foco na eliminação e exposição de risco para as pessoas, foi realizado a criação de um mirante com guarda corpos
INSERT INTO #PVC VALUES (7391, N'81050237', N'81050237', N'Porta sinalizadores e colete', NULL, N'Projects/Projetos', N'falta de um ponto para armazenamento de sinalizadores e coletes. ', N'organização', N'10007', N'01 - Imagens/01 - Antes/7391.jpeg', N'Antes não tinha um lugar definido para armazenar os sinalizadores com o colete refletivo.', N'01 - Imagens/02 - Depois/7391.jpeg', N'Com a aplicação do compartimento e identificação, ganhamos agilidade e organização. com o colete no alcance do colaborador ele não vai deixar de usar o colete refletivo.', NULL, N'Com a aplicação do compartimento e identificação, ganhamos agilidade e organização. com o colete no alcance do colaborador ele não vai deixar de usar o colete refletivo.', N'organização', 0, NULL, NULL, '2026-01-04T00:00:00.000', '2026-01-10T01:29:59.000', N'81050237', NULL, 1);
INSERT INTO #PVC VALUES (7392, N'502163', N'81046990', N'ACESSO SEGURO', NULL, N'Projects/Projetos', N'ESCADA MARINHEIRO COM OXIDAÇÃO E DIFICULDADE NO ACESSO.', N'ELIMINAR ESCADA MARINHEIRO', N'10316', N'01 - Imagens/01 - Antes/7392.jpeg', N'ESCADA MARINHEIRO COM OXIDAÇÃO E DIFICULDADE NO ACESSO.', N'01 - Imagens/02 - Depois/7392.jpeg', N'ELABORAMOS UM PROJETO DE ESCADA PLATAFORMA E SUBSTITUIMOS A ESCADA MARINHEIRO QUE ESTAVA OXIDADA E COM DIFICIL ACESSO PARA QUEM NECESSITA ACESSAR ESTE LOCAL.', NULL, N'PROBLEMA RESOLVIDO.', N'IDENTIFICAR E TRATAR ACESSOS DIFICEIS NA NOSSA ROTINA', 0, NULL, N'REDUÇÃO DE EXPOSIÇÃO OS RISCOS APRESENTADOS COM A BASE COM ALTO NIVEL DE CORROSÃO', '2026-01-08T00:00:00.000', '2026-01-10T11:50:07.000', N'502163', NULL, 1);
INSERT INTO #PVC VALUES (7393, N'502163', N'81012442', N'SUPORTE DE MANGUEIRA', NULL, N'Others/Outros', N'ARE DESORGANIZADA ', N'DEIXAR LOCAL ORGANIZADO', N'10316', N'01 - Imagens/01 - Antes/7393.jpeg', N'AREA COMPLETAMENTE DESORGANIZADA E FORA DE PADRÃO.', N'01 - Imagens/02 - Depois/7393.jpeg', N'REALIZAMOS A MONTAGEM DE SUPORTES PARA ARMAZENAR AS MANGUEIRAS E ORGANIZAR O LOCAL.', NULL, N'PROBLEMA RESOLVIDO, AMBINTE SE TORNOU ORGANIZADO COM UM SIMPLES MUDANÇA.', N'AMBIENTE ORGANIZADO SE TRABALHA MELHOR', 0, NULL, N'A soldagem da chapa metálica substituindo os pranchões de madeira proporcionou maior resistência à umidade, aumentou a vida útil da passarela, garantiu a segurança dos colaboradores e assegurou a proteção adequada do sensor de fim de curso do translado da TR-2010-01.', '2026-01-09T00:00:00.000', '2026-01-10T16:32:11.000', N'502163', NULL, 1);
INSERT INTO #PVC VALUES (7394, N'699785', N'81013620', N'REPOSICIONADO LUZ STROBOL (PISCOFLEX)', NULL, N'Others/Outros', N'DIFICULDADES NA SUBSTITUIÇAO ', N'FACILIDADE NA SUBSTITUIÇAO DO COMPONENTE', N'10144', N'01 - Imagens/01 - Antes/7394.jpeg', N'ANTES O ACESSO ATE O COMPONENTE ERA SOMENTE PELO LADO EXTERNO DO MASTRO COM AUXILIO DA PTA', N'01 - Imagens/02 - Depois/7394.jpeg', N'ATUALMENTE O ACESSO AO COMPONENTE NAO DEPENDE MAIS DO AUXILIO DA PLATAFORMA ELEVATORIA', NULL, N'SIM; OBTEVE-SE UM GANHO SIGNIIFICATIVO NA PRODUTIVIDADE', N'MELHORIA NO PROCESSO', 0, NULL, N'Restrição de acesso dos produtos, praticidade de identificação dos produtos, armazenamento, limpeza e organização.', '2026-01-09T00:00:00.000', '2026-01-10T18:05:14.000', N'699785', NULL, 1);
INSERT INTO #PVC VALUES (7395, N'81046149', N'81040359', N'Espaço Bem-estar', NULL, N'Others/Outros', N'local com ausência de uma área de vivencia e organização de matérias e ferramentas. A falta de uma área de vivencia compromete as condições mínimas de conforto e descanso , favorecendo a fadiga, estresse principalmente em épocas de PGB onde as atividades são mais exaustivas e O tempo de atividade é maior.Quanto a um local pra organização de matérias e armazenamento de ferramentas gera risco de tropeços, quedas,alem de dificultar o acesso rápido aos equipamentos corretos, podendo levar ao uso inadequado ou improviso de ferramentas.Ambas as situações contribuem para um ambiente desorganizado e fora do padrão exigido tanto pela norma quanto pelo nosso sistema de 5S.', N'Melhora ambiente de trabalho, e um local adequado e seguro para colaboradores.', N'10044', N'01 - Imagens/01 - Antes/7395.jpeg', N'local com ausência de uma área de vivencia e organização de matérias e ferramentas. A falta de uma área de vivencia compromete as condições mínimas de conforto e descanso , favorecendo a fadiga, estresse principalmente em épocas de PGB onde as atividades são mais exaustivas e O tempo de atividade é maior.Quanto a um local pra organização de matérias e armazenamento de ferramentas gera risco de tropeços, quedas,alem de dificultar o acesso rápido aos equipamentos corretos, podendo levar ao uso inadequado ou improviso de ferramentas.Ambas as situações contribuem para um ambiente desorganizado e fora do padrão exigido tanto pela norma quanto pelo nosso sistema de 5S.', N'01 - Imagens/02 - Depois/7395.jpeg', N'A padronização da área de vivencia e do local destinado ao armazenamento e organização de ferramentas contribuiu diretamente para a melhoria das condições de trabalho,segurança operacional e o bem-estar das pessoas. Área de vivencia garante condições adequadas de conforto,descanso durante um intervalo e outro de uma atividade, local para hidratação, e proteção contra intempéries, reduzindo a fadiga e o estresse. O local para armazenamento de ferramentas promove uma organização ,identificação visual e fácil acesso aos recursos necessários para execução das tarefas.Reduz o risco de tropeço. quedas,alem de evitar o risco de improvisos de ferramentas, já que as mesmas vão esta disponível e de fácil acesso.', NULL, N'sim! padronização melhoria e organização', N'padronização', 2, 1, N'Com a instalação do guarda-corpo, o risco de queda foi totalmente eliminado no trecho da TR-2012-03. A área passou a atender aos requisitos de segurança, proporcionando mais confiança e segurança aos colaboradores que transitam no local.
INSERT INTO #PVC VALUES (7396, N'81029883', N'81013438', N'Filtragem: Flexibilização de dreno CX-2020-01 ', NULL, N'Others/Outros', N'Acumulo de material no Sump e parada constante dos Filtros. Ocasionado por transbordo da CX-2020-01.', N'Disponibilidade Operacional ', N'10134', N'01 - Imagens/01 - Antes/7396.jpeg', N'Sistema de bombeamento da caixa-2020-01, através das bombas do Salobo 01 e 02, com linha de recalque unificada, ocasionando a disponibilidade de apenas umas das bombas em operação e constante desgaste pré-maturo de rolamento devido retorno na bomba através da linha de recalque. ', N'01 - Imagens/02 - Depois/7396.jpeg', N'Implementado solução, através da individualização das bombas na linha de recalque, aumentando a disponibilidade de ativos para drenagem da CX-2020-01 e redução de falhas e quebra das bombas por retorno de recalque.', NULL, N'Sim.
INSERT INTO #PVC VALUES (7397, N'81029883', N'81013438', N'SUMP da Filtragem ', NULL, N'Open Pit/Poço aberto', N'Sedimentação e acumulo de material no Sump da Filtragem.', N'Otimizar sistema de homogeneização do Sump  ', N'10302', N'01 - Imagens/01 - Antes/7397.jpeg', N'sedimentação de material no Sump da Filtragem.
INSERT INTO #PVC VALUES (7398, N'1008368', N'1008368', N'Replacing Steam trap', NULL, N'No Replication/Sem replicação', N'Trap Not working steam was just pushing right through causing excess steam to vent through stack', N'Replace with new trap without involving maintenance', N'0', N'01 - Imagens/01 - Antes/7398.jpeg', N'Old Steam Trap was not working allowing Steam to just pass right on through not forming condensate
(Old Trap had been removed when Picture was taken)', N'01 - Imagens/02 - Depois/7398.jpeg', N'New steam trap installed allowing a change from steam to condensate for reuse, rather than steam venting through stack', NULL, N'Yes problem solved, Trap was replaced and is working good', N'Having Operations complete task reduces maintenance costs', 3000, 3, N'Tivemos um ótimo resultado e fomos parabenizados pelos visitantes de outras áreas.', '2026-01-10T00:00:00.000', '2026-01-11T17:56:07.000', N'1008368', NULL, 1);
INSERT INTO #PVC VALUES (7399, N'81022599', N'81022599', N'Nova tubulação de Bentonita', NULL, N'Others/Outros', N'Antes, a tubulação de Bentonita era dentro da canaleta da casa química, por conta disso ela ficava cheia de resíduos e podendo obstruir.', N'Melhorar a visibilidade da tubulação pelo operador e pela manutenção.', N'10302', N'01 - Imagens/01 - Antes/7399.jpeg', N'Parte da Tubulação de Bentonita passava por dentro da canaleta da casa química, a tubulação ficava submersa nos resíduos da canaleta, e quando obstruía tinha que limpar toda a canaleta para desmontar a tubulação e tirá-la de dentro, gerando mais tempo de manutenção.', N'01 - Imagens/02 - Depois/7399.jpeg', N'Foi montado uma tubulação aérea, onde o operador tem uma visibilidade melhor na hora da inspeção, podendo identificar problemas de obstrução, quebra ou vazamento, facilitando também para manutenção montagem e desmontagem da tubulação.', NULL, N'O problema foi resolvido, o operador tem mais visibilidade para identificar qualquer problema na tubulação.', N'Sempre temos algo a melhorar na nossa área.', 0, NULL, N'Ganhos: Redução de esforço físico; Melhoria Ergonômica; Aumento da qualidade da amostragem; Eficiência Operacional; Redução de riscos de acidentes; Inovação Tecnológica; Redução de custos indiretos; Valorização da equipe entre outros ganhos.  ', '2026-01-07T00:00:00.000', '2026-01-11T18:03:10.000', N'81022599', NULL, 1);
INSERT INTO #PVC VALUES (7400, N'607144', N'81016334', N'3850L Storage Standardization Method', NULL, N'Underground/Subterrâneo', N'Materials being stored in the 3850L storage are mismanaged and causing housekeeping issues.', N'Improvement to housekeeping and material management', N'10238', N'01 - Imagens/01 - Antes/7400.jpeg', N'Disorganized storage of supplies creating safety and efficiency gaps.', N'01 - Imagens/02 - Depois/7400.jpeg', N'Improvement to conditions.  Storage layout with designated group section will make this solution sustainable.', NULL, N'Yes.  Area is now cleaned up and laydown chart makes this sustainable.', N'Organization, process.', 0, NULL, NULL, '2026-01-11T00:00:00.000', '2026-01-12T08:44:24.000', N'607144', NULL, 1);
INSERT INTO #PVC VALUES (7401, N'983254', N'983254', N'Comunicação de acesso na britagem', NULL, N'Projects/Projetos', N'Perda de tempo aguardando comunicação com operador da britagem para fazer a liberação de acesso fisicamente no portão de acesso a britagem primária', N'Redução do tempo de espera de uma média de 5 minutos para liberação de acesso na área da britagem, para 20 segundos. a', N'10054', N'01 - Imagens/01 - Antes/7401.jpeg', N'Para acessar a área da britagem, o colaborador dependia de comunicação via rádio ou do apoio de outro colaborador com rádio. O acesso precisa ser autorizado pelo operador da cabine, que, após avaliar as condições operacionais, se deslocava para abertura do portão. Esse processo acarretava interrupção temporária no monitoramento do basculamento trazendo riscos a operação, expondo o colaborador a riscos ergonômicos e leva cerca de 10 minutos em média.', N'01 - Imagens/02 - Depois/7401.jpeg', N' Foi instalada uma fechadura eletrônica com acesso remoto, possibilitando ao operador, diretamente da cabine, visualizar, comunicar-se e autorizar o acesso por meio do destravamento do portão. A melhoria eliminou a necessidade de deslocamento do operador, uso de rádio e afastamento do posto de trabalho, reduzindo o tempo do processo de 10 minutos para cerca de 20 segundos.', NULL, N'Meta superada, eliminamos alguns riscos e reduzimos o tempo da atividade em 96,67%. ', N'Otimização de tempo', 2000, 1, N'• Realizado um breve levantamento de  ocorrências neste local, onde a média anual, era aproximadamente 4  furtos, totalizando um valor estimado em: R$ 113.650/ano, com a compra de cabos elétricos, para substituir os furtados.
INSERT INTO #PVC VALUES (7402, N'550609', N'550609', N'TAG DO ATIVO', NULL, N'Others/Outros', N'NÃO HAVIA INDETIFICAÇÃO VISIVEL PARA EQUIPAMENTO TO-5009-11 DIFICULTANDO RASTREABILIDADE E ENSINO AO NOVO COLABORADORES ', N'IDENTIFCAÇÃO E 5S ', N'10199', N'01 - Imagens/01 - Antes/7402.jpeg', N'NÃO HAVIA INDENTIFICAÇÃO VISIVEL PARA EQUIPAMENTO TO-5009-11 DIFICULTANDO RASTREABILIDADE E ENSINO AO NOVO COLABORADORES ', N'01 - Imagens/02 - Depois/7402.jpeg', N'Foi identificado o componente com tag devidamente fixada, apresentando boa visibilidade e clareza, garantindo fácil identificação para todos os colaboradores. Essa prática contribui para maior conhecimento e rastreabilidade dos equipamentos, atendendo aos padrões de segurança e organização estabelecidos.', NULL, N'Não foram identificados problemas relacionados à visibilidade ou clareza da tag neste caso específico.
INSERT INTO #PVC VALUES (7403, N'472995', N'472995', N'BASE COM FORMATO U', NULL, N'Others/Outros', N'Nas paradas de manutenção para troca dos revestimentos inferior da caixa de pedra no chute de descarga do alimentador, equipamento 2051AL01. ocorria vários princípios de incêndio nas peças das guias de PU e na correia, causando alto risco de incêndio, posição ergonômica irregular, também solicitação de montagem e desmontagem de andaime elevando número de funcionário e tempo de manutenção.', N'ELIMINAR MONTAGEM DE ANDAIME, PRINCIPIO DE INCENDIO NAS GUIAS DE PUR E NA CORREIA ', N'10264', N'01 - Imagens/01 - Antes/7403.jpeg', N'Acesso para corte e fixação dos revestimentos pela parte externa do chute, projeção de fogo na guia PU e na correia, trabalho em altura, posição ergonômica irregular, elevado tempo de manutenção e elevado número de pessoas para realização da atividade.', N'01 - Imagens/02 - Depois/7403.jpeg', N'Confecção e montagem da base em formato U, para fixar os revestimentos pelo acesso interno do chute e para conter projeção do fogo causado pelo oxicorte ou máquina de solda. Eliminando possíveis princípios de incêndio, montagem e desmontagem andaime, posição ergonômica irregular', NULL, N'Após confecção e instalação da base em formato U não ove mas projeção de fogo na correia e na guia PU nem necessidade de montagem e desmontagem de andaime', N'Eliminação de risco de incêndio, trabalho em altura, posição ergonômica', 15000, 1, N'Redução de tempo de busca de ferramentas, aumento da eficiência operacional da equipe de manutenção, melhoria na organização limpeza dos carrinhos de ferramentas. ', '2025-12-10T00:00:00.000', '2026-01-12T16:47:09.000', N'472995', NULL, 1);
INSERT INTO #PVC VALUES (7404, N'1008368', N'1008368', N'Replacing Steam Trap', NULL, N'No Replication/Sem replicação', N'Steam Trap 0071 was passing high pressure steam right through trap and not forming any condensate to return to Condensate Vessel which is then pumped back for re-use in boiler room. the steam was going back to condensate vessel as steam and going to atmosphere via vessel''s vent.', N'Replace with new trap without involving maintenance personnel', N'0', N'01 - Imagens/01 - Antes/7404.jpeg', N'Steam Trap 0071 was passing high pressure steam right through trap and not forming any condensate to return to Condensate Vessel which is then pumped back for re-use in boiler room. the steam was going back to condensate vessel as steam and going to atmosphere via vessel''s vent.', N'01 - Imagens/02 - Depois/7404.jpeg', N'New steam trap installed allowing a change from steam to
INSERT INTO #PVC VALUES (7405, N'81040073', N'547828', N'BASE TAMBORES DE REFULGO', NULL, N'No Replication/Sem replicação', N'ANTERIORMENTE A BASE DOS TAMBORES DE REFULGO ESTAVA COM ALTO NIVEL DE CORROSÃO E COM CHAPAS DANIFICADAS', N'MELHORAR CONFIÇÃO DE TRABALHO', N'10044', N'01 - Imagens/01 - Antes/7405.jpeg', N'ANTERIORMENTE A BASE DOS TAMBORES DE REFULGO ESTAVA COM ALTO NIVEL DE CORROSÃO E COM CHAPAS DANIFICADAS, PODENDO OCASIONAR EM ACIDENTES OU INCIDENTES AO RETIRAR OS TAMBORES.', N'01 - Imagens/02 - Depois/7405.jpeg', N'FOI FABRICADO UMA NOVA BASE COM CHAPAS MAIS RESISTENTES PARA SUPORTAR O PESO DOS TAMBORES DE REFULGO, ELIMINANDO RESCOS DE ACIDENTES NO LOCAL.', NULL, N'SIM, PORQUE HOJE SE TRABALHA COM MAIS SEGURANÇA TENDO ESTRUTURA DA BASE E GRADES DE PISO NOVAS. ', N'MANTER A AREA EM CONDIÇÕES DE TRABALHO É MAIS SEGURO', 0, NULL, NULL, '2026-01-09T00:00:00.000', '2026-01-13T09:55:24.000', N'81040073', NULL, 1);
INSERT INTO #PVC VALUES (7406, N'548018', N'502688', N'Substituição de pranchões de madeira por chapa metálica na passarela da TR-2010-01', NULL, N'Projects/Projetos', N'A passarela da TR-2010-01 era composta por dois pranchões de madeira, material inadequado para ambiente com presença constante de umidade e água. Com o passar do tempo, a madeira tende a apodrecer, perder resistência mecânica e oferecer risco de queda aos colaboradores, além de comprometer a proteção do sensor de fim de curso do translado.
INSERT INTO #PVC VALUES (7407, N'514353', N'514353', N'Casa de Tinta Móvel', NULL, N'Others/Outros', N'Anteriormente, para realização de atividades nas frentes de serviço, os produtos químicos de menor proporção eram transportados em bacias de contenção, ocasionando exposição aos colaboradores e proporcionando riscos para eventos ambientais.', N'Mitigar os riscos a exposião aos produtos quimicos, facilitar o transporte de produtos de baixa proporção para as frentes de seriço, melhorar o fluxo de armazenamento de produtos nas frentes.', N'10017', N'01 - Imagens/01 - Antes/7407.jpeg', N'Anteriormente, nas frentes de serviço, produtos químicos em menor quantidade eram transportados em bacias de contenção, gerando exposição dos colaboradores e riscos ambientais.', N'01 - Imagens/02 - Depois/7407.jpeg', N'A casa móvel para produtos químicos aumenta a segurança, agiliza o transporte e melhora o armazenamento nas frentes de serviço, com acesso restrito a pessoas autorizadas.', NULL, N'Praticidade no transporte de produtos, melhoria visual na frente de serviço. Restrição de acesso dos produtos, praticidade de identificação dos produtos, armazenamento, limpeza e organização.', N'Praticidade no transporte de produtos.', 0, NULL, N'Redução de exposição de colaboradores na área. ', '2026-01-01T00:00:00.000', '2026-01-13T10:13:40.000', N'514353', NULL, 1);
INSERT INTO #PVC VALUES (7408, N'548018', N'81039135', N' Instalação de Guarda-corpo na Casa de Transferência TR-2012-03', NULL, N'Others/Outros', N' Antes da implementação, as bordas do piso da Casa de Transferência 2012-03 não possuía nenhum tipo de proteção, expondo os colaboradores ao risco de queda durante a realização de atividades no local.
INSERT INTO #PVC VALUES (7409, N'548018', N'81056646', N'Instalação de Grade de Proteção no Acionamento do Tambor do Braço Torque da TR-2009-07', NULL, N'Others/Outros', N'O acionamento do tambor do braço torque da TR-2009-07 operava com componentes rotativos expostos, sem proteção física adequada.', N'Garantir a segurança dos colaboradores através da proteção das partes móveis do acionamento do tambor do braço torque, atendendo aos requisitos da NR-12 (Segurança no Trabalho em Máquinas e Equipamentos) e prevenindo acidentes com máquinas rotativas.', N'10031', N'01 - Imagens/01 - Antes/7409.jpeg', N'O acionamento do tambor do braço torque da TR-2009-07 operava com componentes rotativos expostos, sem proteção física adequada.', N'01 - Imagens/02 - Depois/7409.jpeg', N'Com a instalação da grade de proteção, o acionamento do tambor do braço torque passou a operar de forma segura, atendendo à NR-12, eliminando o risco de contato com partes móveis e aumentando a confiabilidade do equipamento.', NULL, N'Garantir a segurança dos colaboradores através da proteção das partes móveis do acionamento do tambor do braço torque, atendendo aos requisitos da NR-12 (Segurança no Trabalho em Máquinas e Equipamentos) e prevenindo acidentes com máquinas rotativas.
INSERT INTO #PVC VALUES (7410, N'1014415', N'1014415', N'SDx (Document Control) Improvement', NULL, N'Others/Outros', N'In 2025, VNL Central Engineering rolled out a new document control system, SDx, for Voisey''s Bay. Though a useful tool, the ability to search and retrieve document for a specific scope is often challenging, with limited filters able to be set (largely limited to WBS area, discipline, drawing type, and title - where the titles are often general and broad).
INSERT INTO #PVC VALUES (7411, N'701391', N'701391', N'Mirante barragem', NULL, N'No Replication/Sem replicação', N'Ponto de lançamento de rejeito por bombeamento sem estacionamento e sem ponto para visualização do lançamento.', N'Padronizar com estacionamento e mirante.', N'10054', N'01 - Imagens/01 - Antes/7411.jpeg', N'Ponto de lançamento de rejeito sem estacionamento para veículos e sem mirante para visualização.', N'01 - Imagens/02 - Depois/7411.jpeg', N'Área padronizada e sinalizada, gerando condições seguras para visitação ao ponto de lançamento.', NULL, N'Sim, resolvemos o problema, deixamos a área mais segura para visitação e sinalizamos com as devidas orientações.', N'5´s  sempre é muito importante.', 0, NULL, N'Ergonomia: Redução de esforço físico e movimentos inadequados.
INSERT INTO #PVC VALUES (7412, N'81036794', N'81006144', N'Implantação do trado elétrico à bateria', NULL, N'No Replication/Sem replicação', N'Atividade de amostragem de mina realizada com a ferramenta denominada Chuncho (cabo de madeira e chanfro cilíndrico metálico), ocasionando grande esforço físico, impacto nos braços e ombros e postura que causa maior cansaço. 
INSERT INTO #PVC VALUES (7413, N'81036658', N'81036658', N'Reactor Bell Housing Modification', NULL, N'No Replication/Sem replicação', N'The existing bell housing design didn''t have any good way of pulling the housing off or re installing. Existing process but workers close to hazards and needed a solution to keep workers out of danger as well as lower the manpower required to complete the job. Existing design required pulling with come alongs from steelwork difficult to access then using an Enerpac between the reactor and housing end flanges.', N'Provide an Engineering solution to allow easy removal and installation of the reactor Bell Housing', N'10076', N'01 - Imagens/01 - Antes/7413.jpeg', N'The existing bell housing design didn''t have any good way of pulling the housing off or re installing. Existing process but workers close to hazards and needed a solution to keep workers out of danger as well as lower the manpower required to complete the job. Existing design required pulling with come alongs from steelwork difficult to access then using an Enerpac between the reactor and housing end flanges.', N'01 - Imagens/02 - Depois/7413.jpeg', N'The solution was to slit the reactor bell housing into two halves and use a custom machined flange with threaded holes into blind holes that allow the flange to work as a "puller". With this design, the bell housing can be removed and installed using the new flanged connection. Because the one half of the bell housing (half connected to reactor end flange) had no friction parts. Once the other half is removed (this end has a bearing inside) the bell housing can be removed using the overhead monorail.', NULL, N'Safer and hopefully more reliable.', N'A mechanical solution minimizes potential for failure.', 0, NULL, N'Ganho em tempo e confiabilidade para o processo', '2026-01-01T00:00:00.000', '2026-01-13T15:10:52.000', N'81036658', NULL, 1);
INSERT INTO #PVC VALUES (7414, N'486869', N'487651', N'PROTEÇÃO DE AÇO', NULL, N'Others/Outros', N' O PROBLEMA PRINCIPAL É: CONSTANTES  FURTOS DOS CABOS DE ALIMENTAÇÃO DAS BOMBAS DE 440v, NA CAVA MATA.
INSERT INTO #PVC VALUES (7415, N'1005608', N'1005608', N'Develop PSV Maintenance Standard', NULL, N'Concentration/Concentração', N'PSV maintenance plans are either missing or not in line with regulations. ', N'Develop of standard for Voiseys bay that complies with regulations', N'10096', N'01 - Imagens/01 - Antes/7415.jpeg', N'PSV Maintenance is governed by NL BPV regulations that set out requirements as defined in CSA B51. Many PSV''s on site are missing or have maintenance plans that are not in line with the regulations. The regulations are complicated and often difficult to understand. ', N'01 - Imagens/02 - Depois/7415.jpeg', N'The Voisey''s Bay PSV Maintenance Strategy document was developed to outline the requirements for site. This document contains an easy to understand requirement with specific site references to make rollout of a revised maintenance program for PSV''s easy. In addition, this strategy has been rolled out already to all criticality ''A'' PSV''s - with Crit. B''s in the works. ', NULL, N'Yes. We are now in compliance. ', N'Simplification and rollout of regs', 0, NULL, N'This saves valuable time each month for VNL Finance and Central Engineering. ', '2026-01-12T00:00:00.000', '2026-01-14T09:50:44.000', N'1005608', NULL, 1);
INSERT INTO #PVC VALUES (7416, N'81034443', N'81034443', N'Implementação 5s: Identificação Eficaz de Carrinhos de Ferramentas. ', NULL, N'Others/Outros', N'A falta de identificação clara e padronizada nos carrinhos de ferramentas da manutenção gera perda de tempo na localização de ferramentas e equipamentos, impactando a eficiência operacional e a produtividade da equipe.', N'Melhorar a identificação e organização dos carrinhos de ferramentas da área de manutenção, reduzindo o tempo de busca e aumentando a eficiência operacional.', N'10140', N'01 - Imagens/01 - Antes/7416.jpeg', N'A falta de identificação clara e padronizada nos carrinhos de ferramentas da manutenção gera perda de tempo na localização de ferramentas e equipamentos, impactando a eficiência operacional e a produtividade da equipe.', N'01 - Imagens/02 - Depois/7416.jpeg', N'- Implementar identificação padronizada e visível nos carrinhos de ferramentas utilizando, cores específicas por setor e informações do responsável.
INSERT INTO #PVC VALUES (7417, N'487847', N'487847', N'Planilha ISO 4406:1999', NULL, N'Others/Outros', N'A norma ISO 4406:1999 define o padrão internacional para classificar a contaminação sólida em fluidos hidráulicos e de lubrificação através de um código de três números (ex: 18/16/13).determinando a limpeza. onde o nosso equipamento Viscosímetro faz o calculo automático, com a aquisição de um novo equipamento PAMAS ele não faz o calculo da ISO.', N'O objetivo é manter o cliente informado dos resultados para tomada de decisão', N'10171', N'01 - Imagens/01 - Antes/7417.jpeg', N'A norma ISO 4406:1999 define o padrão internacional para classificar a contaminação sólida em fluidos hidráulicos e de lubrificação através de um código de três números (ex: 18/16/13).determinando a limpeza. onde o nosso equipamento Viscosímetro faz o calculo automático, com a aquisição de um novo equipamento PAMAS ele não faz o calculo da ISO.', N'01 - Imagens/02 - Depois/7417.jpeg', N'Desenvolvemos uma planilha que faz o calculo da ISO a partir das informações inseridas nela. 
INSERT INTO #PVC VALUES (7418, N'81059060', N'516988', N'TRAVA DA BALANÇA DO TRUCK', NULL, N'Others/Outros', N'balança dos trucks sem travamento, dificultando a instalação.', N'A trava da balança do truck impossibilita o risco de empenar, emantendo totalmente presa.', N'10139', N'01 - Imagens/01 - Antes/7418.jpeg', N'Balança dos Trucks sem travamento, dificultando a instalação.', N'01 - Imagens/02 - Depois/7418.jpeg', N'Foi confeccionado o suporte reforçado para travamento da balança, garantindo fixação total e eliminando riscos de empenamento.', NULL, N'Sim o problema foi resolvido
INSERT INTO #PVC VALUES (7419, N'81034922', N'81055026', N'Legendas dos índices de DBU', NULL, N'Others/Outros', N'Não tínhamos um local onde pesquisar e entender o significado das siglas do DBU.', N'Ter um melhor entendimento do significado das siglas do DBU', N'10140', N'01 - Imagens/01 - Antes/7419.jpeg', N'Não tínhamos um local onde pesquisar e entender o significado das siglas do DBU, dificultando o entendimento dos prazos e tempo correto de realizar as aplicações.', N'01 - Imagens/02 - Depois/7419.jpeg', N'Foi realizado um quadro explicando no detalhe o significado de cada sigla, período de aplicação e deixado a disposição de todos para pesquisa nas salas de FMDS da oficina, Kimbo e estacionamento do 320.', NULL, N'Sim, com essa melhoria conseguimos fazer todas as aplicações nos períodos certos.', N'É necessário mater a rotina de melhoria continua para estar sempre melhorando nos nossos processos.', 0, NULL, N'Segurança e agilidade durante a atividade de limpeza no chute e facilidade na visualização durante as inspeções. ', '2026-01-10T00:00:00.000', '2026-01-14T11:18:16.000', N'81034922', NULL, 1);
INSERT INTO #PVC VALUES (7420, N'503556', N'503556', N'Melhoria que Gira ', NULL, N'No Replication/Sem replicação', N'Falha no Inclinômetro Ponte B2 Konecrane', N'Eliminar falhas do inclinômetro ', N'10147', N'01 - Imagens/01 - Antes/7420.jpeg', N'A Ponte B2 apresentou falhas recorrentes no inclinômetro, Essas falhas resultavam na interrupção do ciclo automático, forçando a operação em modo semiautomático.
INSERT INTO #PVC VALUES (7421, N'81006670', N'81053737', N'Sistema de Evaporação de Água Residual do Ar-Condicionado.', NULL, N'Others/Outros', N'Água residual do ar-condicionado escorrendo externamente.', N'Eliminar o descarte inadequado da água de condensação.  Implementar um sistema de evaporação eficiente.  Melhorar segurança, organização e confiabilidade da instalação.  Atender boas práticas industriais (5S / Manutenção / Meio Ambiente).', N'10144', N'01 - Imagens/01 - Antes/7421.jpeg', N'Dreno do ar-condicionado sem destino definido.
INSERT INTO #PVC VALUES (7422, N'979633', N'979633', N'Adaptação de Pipeta Pasteur para Controle de Fluxo', NULL, N'Others/Outros', N'Vazão da Pipeta Pasteur superior, podendo impactar na análise devido a  precisão, identificado na rotina ', N'aumentar a precisão na lavagem das pérolas de ouro', N'10235', N'01 - Imagens/01 - Antes/7422.jpeg', N'Utilizava-se a pipeta Pasteur de polietileno (como a da imagem), um utensílio comum de laboratório. Embora prática para transferência geral de líquidos, sua abertura padrão libera um fluxo de água que, para a frágil pérola de ouro, é muito agressivo, aumentando o risco de perda de material e erros na pesagem final.', N'01 - Imagens/02 - Depois/7422.jpeg', N'A pipeta Pasteur convencional foi modificada com uma ponteira de microvolume, reduzindo o orifício de saída.
INSERT INTO #PVC VALUES (7423, N'81051007', N'509650', N'Melhoria Ergonômica e Segura no Processo da Volumetria', NULL, N'Others/Outros', N'Durante a titulação das amostras, era necessário adicionar manualmente três reagentes, o que expunha o colaborador a riscos como:
INSERT INTO #PVC VALUES (7424, N'81051007', N'939520', N'Substituição de Limpador Improvisado por Ferramenta Ergonômica', NULL, N'Others/Outros', N'Era utilizado um limpador improvisado com haste simples e esponja enrolada, que apresentava baixa durabilidade, pouca eficiência na limpeza e não oferecia ergonomia adequada para o operador.', N'Garantir maior ergonomia, segurança e eficiência no processo de limpeza de vidrarias, reduzindo riscos e melhorando a qualidade do trabalho.', N'10235', N'01 - Imagens/01 - Antes/7424.jpeg', N'Antes:
INSERT INTO #PVC VALUES (7425, N'497889', N'497889', N'Cockpit OM - Dashboard Aprovisionador', NULL, N'No Replication/Sem replicação', N'Tinhamos um problemas em visualizar as OM''s com seus status e fazer as tratativas.', N'Ter mais facilidade em visualizar OM''s e com isso fazer as tratativas de todos os status', N'10023', N'01 - Imagens/01 - Antes/7425.jpeg', N'O aprovisionador perdia muito tempo para visualizar a carteira e verificar os status para tratativa.', N'01 - Imagens/02 - Depois/7425.jpeg', N'Com essa ferramenta, o Aprovisionador tem maior visualização e facilidade sem perda de tempo de toda a carteira para tratativa.', NULL, N'Problema resolvido sim, pois o aprovisionador tem muito mais facilidade em enxergar os status para tratativas.', N'Melhor visualização de OM''s do Aprovisionamento', 0, NULL, N'.', '2026-01-12T00:00:00.000', '2026-01-14T14:41:40.000', N'497889', NULL, 1);
INSERT INTO #PVC VALUES (7426, N'81016164', N'81016164', N'Processo de Melhoria – Toca da ponteira de abastecimento de corpos moedores caixas de alimentação EE-2308SA-01 Flotação III', NULL, N'Others/Outros', N'Deficiência para dosagem de bolas na Caixa por falta de ponteiras para Rasgo/Corte das sacolas Begues.', N'Processo e Produção', N'10178', N'01 - Imagens/01 - Antes/7426.jpeg', N'Foi identificado a dificuldade/Agilidade para dosagem de corpos moedores por falta de ponteiras para Rasgo/Corte das sacolas Begues.
INSERT INTO #PVC VALUES (7427, N'81045764', N'81045764', N'Utilize Storage/Stock Room for Green shirts', NULL, N'Others/Outros', N'Uniform clothes, no place to keep stock in PCR', N'Make use of spare room', N'10255', N'01 - Imagens/01 - Antes/7427.jpeg', N'Spare room in Admin building not being used.  Green shirts were in the basement not accessible.', N'01 - Imagens/02 - Depois/7427.jpeg', N'Clothes are organized and easily accessible now in the spare room.', NULL, N'Yes, Stock is easily accessible.', N'Organization reduces time.', 0, NULL, N' Organização e 5s das mochilas no container de vivência.', '2026-01-13T00:00:00.000', '2026-01-14T15:13:12.000', N'81045764', NULL, 1);
INSERT INTO #PVC VALUES (7428, N'81020064', N'1014384', N'Invoice Review Process - Labrador Operations', NULL, N'Projects/Projetos', N'Volume of engineering invoices to be processed is overwhelming the capacity of the finance clerks. In order to ensure accurate progress tracking and accountability for cost, each engineering project is assigned it''s own PO#. We may have 20+ active projects at one time. This has created significant administrative effort to have an individual invoice cover sheet signed off for every project.    ', N'Eliminate wasted effort in the invoice SES process', N'10311', N'01 - Imagens/01 - Antes/7428.jpeg', N'Volume of engineering invoices to be processed is overwhelming the capacity of the finance clerks. In order to ensure accurate progress tracking and accountability for cost, each engineering project is assigned it''s own PO#. We may have 20+ active projects at one time. This has created significant administrative effort to have an individual invoice cover sheet signed off for every project.   ', N'01 - Imagens/02 - Depois/7428.jpeg', N'One coversheet with an attached list of reviewed invoices implemented. We are already tracking our invoicing and use this to attach the relevant info needed by the admin clerk to generate the SES #s. This saves valuable time each month for VNL Finance and Central Engineering. ', NULL, N'This process change is a step improvement in the invoice review process. ', N'Discipline and patience is needed for alignment to make process changes.', 0, NULL, N'Houve redução do tempo de preparação de reagente e do ensaio.', '2025-12-31T00:00:00.000', '2026-01-14T17:01:44.000', N'81020064', NULL, 1);
INSERT INTO #PVC VALUES (7429, N'81048028', N'81048028', N'Formulário Digital Para Entrega de Ferramentas', NULL, N'No Replication/Sem replicação', N'Anteriormente, o controle de entrega e empréstimo de ferramentas era realizado por meio de formulários manuscritos. Esse método apresentava diversas limitações, tais como dificuldade de leitura, risco de preenchimento incorreto, extravio de informações, retrabalho para conferência e baixa rastreabilidade dos dados.', N'Com o objetivo de melhorar a padronização, a confiabilidade das informações e a eficiência do processo, o formulário passou a ser preenchido de forma digital. A nova metodologia permite maior clareza nos registros, redução de erros de interpretação, agilidade no preenchimento e facilidade na consulta e arquivamento dos dados.', N'10140', N'01 - Imagens/01 - Antes/7429.jpeg', N'Anteriormente, o controle de entrega e empréstimo de ferramentas era realizado por meio de formulários manuscritos. Esse método apresentava diversas limitações, tais como dificuldade de leitura, risco de preenchimento incorreto, extravio de informações, retrabalho para conferência e baixa rastreabilidade dos dados.', N'01 - Imagens/02 - Depois/7429.jpeg', N'Com o objetivo de melhorar a padronização, a confiabilidade das informações e a eficiência do processo, o formulário passou a ser preenchido de forma digital. A nova metodologia permite maior clareza nos registros, redução de erros de interpretação, agilidade no preenchimento e facilidade na consulta e arquivamento dos dados.
INSERT INTO #PVC VALUES (7430, N'81048028', N'81048028', N'Implantação de Tabela de Conversão de Medidas na Ferramentaria', NULL, N'No Replication/Sem replicação', N'A ferramentaria não possuía uma tabela de conversão de medidas (polegadas x milímetros) disponível no local de uso. Essa ausência gerava dúvidas recorrentes durante a seleção de ferramentas, aumento do tempo de atendimento, dependência de consultas externas e risco de erro na escolha das medidas, impactando a produtividade e a qualidade das atividades.', N'Disponibilizar uma tabela de conversão de fácil visualização no ponto de uso. Reduzir o tempo gasto na conversão de medidas durante o atendimento na ferramentaria. Minimizar erros na seleção de ferramentas por divergência de unidades de medida. Apoiar a padronização e a gestão visual do ambiente de trabalho.', N'10140', N'01 - Imagens/01 - Antes/7430.jpeg', N'A ausência de uma referência visual padronizada obrigava os colaboradores a realizar conversões de forma empírica ou a interromper a atividade para buscar informação em outros meios. Essa condição aumentava o tempo de atendimento na ferramentaria, gerava dependência de terceiros e elevava o risco de erros na escolha de ferramentas, impactando diretamente a produtividade e a qualidade da execução das tarefas.', N'01 - Imagens/02 - Depois/7430.jpeg', N'Com a implantação da tabela de conversão em local estratégico, as informações passaram a estar disponíveis no ponto de uso, permitindo consultas rápidas e seguras. A melhoria reduziu interrupções, aumentou a autonomia dos colaboradores e contribuiu para maior padronização, agilidade e confiabilidade no processo de retirada e utilização de ferramentas.', NULL, N'As metas estabelecidas foram atendidas, uma vez que a tabela de conversão foi disponibilizada em local estratégico, reduzindo o tempo de consulta, minimizando erros na seleção de ferramentas e melhorando a fluidez do atendimento na ferramentaria. A solução implantada atendeu plenamente ao objetivo de apoiar a padronização e a eficiência operacional.', N'Informações técnicas disponíveis no ponto de uso aumentam a eficiência operacional. A gestão visual é uma ferramenta eficaz para reduzir erros e retrabalho. Pequenas melhorias de baixo custo podem gerar impacto significativo no processo. A padronização contribui para maior autonomia dos colaboradores.', 0, NULL, N'.', '2026-01-14T00:00:00.000', '2026-01-15T03:28:07.000', N'81048028', NULL, 1);
INSERT INTO #PVC VALUES (7431, N'81048028', N'81057153', N'suporte para locomoção de calços', NULL, N'No Replication/Sem replicação', N'Não havia dispositivo para movimentação de calços, exigindo esforço físico excessivo, postura inadequada e manuseio inseguro durante o transporte. Essa condição aumentava o risco de lesões ergonômicas, acidentes operacionais e danos ao equipamento, além de impactar a eficiência da atividade.', N'Melhorar a ergonomia no manuseio e transporte dos calços. Reduzir esforço físico e risco de lesões aos colaboradores. Aumentar a segurança operacional durante a movimentação do equipamento. Padronizar o dispositivo conforme a necessidade real da atividade.', N'10140', N'01 - Imagens/01 - Antes/7431.jpeg', N'A movimentação do calço era realizada de forma pouco ergonômica, com necessidade de ajustes manuais frequentes e exposição do colaborador a posturas inadequadas, contrariando boas práticas de segurança e ergonomia.', N'01 - Imagens/02 - Depois/7431.jpeg', N'Com a adequação do dispositivo, a movimentação passou a ser realizada de forma mais segura e ergonômica, reduzindo riscos operacionais, melhorando a eficiência da atividade e promovendo maior conforto ao colaborador.', NULL, N'As metas estabelecidas foram atingidas com sucesso. Houve melhoria significativa na ergonomia, redução do esforço físico, aumento da segurança na movimentação do calço e maior padronização do processo, confirmando a efetividade do Kaizen implementado.', N'Adequações simples em equipamentos podem gerar grandes ganhos em segurança e ergonomia. A observação da atividade no campo é fundamental para identificar oportunidades de melhoria. Ergonomia e segurança devem ser consideradas desde a concepção até o uso do equipamento. A melhoria contínua contribui para a redução de riscos e aumento da eficiência operacional.', 0, NULL, N'.', '2026-01-14T00:00:00.000', '2026-01-15T06:13:17.000', N'81048028', NULL, 1);
INSERT INTO #PVC VALUES (7432, N'494528', N'496933', N'Chute iluminado.', NULL, N'Others/Outros', N'Baixa visibilidade durante limpeza interna no chute do AL-411-01 devido falta de iluminação na parte interna do chute do AL-411-01.', N'Melhorar visibilidade no chute durante a limpeza.', N'10297', N'01 - Imagens/01 - Antes/7432.jpeg', N'Pouca visibilidade dentro do chute durante atividade de limpeza interna no chute.', N'01 - Imagens/02 - Depois/7432.jpeg', N'Foi instalado um refletor num ponto a permitir iluminar dentro do chute.', NULL, N'problema resolvido ', N'Uma solução simple e obvia e eficaz. ', 0, NULL, N'.', '2026-01-14T00:00:00.000', '2026-01-15T06:28:39.000', N'494528', NULL, 1);
