INSERT INTO #PVC VALUES (7708, N'66944', N'66944', N'Gráfico de percentual diário de material alimentado na britagem', NULL, N'No Replication/Sem replicação', N'Percentual de massas planejadas para alimentação era calculada manualmente pela equipe do Laboratório de Processo.', N'Definir percentual de massas por qualidades alimentadas', N'10162', N'01 - Imagens/01 - Antes/7708.jpeg', N'Antes tínhamos apenas a imagem da tabela do planejado na alimentação. A equipe do Laboratório de processo precisava digitar a planilha e gerar o gráfico com percentual de contribuição de cada frente de lavra.', N'01 - Imagens/02 - Depois/7708.jpeg', N'Gráfico inserido através de tabela dinâmica, sem necessidade de digitar os dados e compartilhado juntamente com a planilha, via e-mail e em grupo.', NULL, N'O problema foi resolvido - SIM', N'A comunicação entre as áreas nos fez conhecer as necessidades e reduzir retrabalho', 0, NULL, N'DEPOIS DA MELHORIA
