INSERT INTO #PVC VALUES (7723, N'550508', N'541883', N'Painel de acompanhamento de reforma', NULL, N'Others/Outros', N'Foi constatada a inexistência de acompanhamento técnico e operacional da reforma em execução, gerando risco de falhas, retrabalho e desvios de planejamento.”', N'otimizar o fluxo operacional', N'10081', N'01 - Imagens/01 - Antes/7723.jpeg', N'Foi constatada a inexistência de acompanhamento técnico e operacional da reforma em execução, gerando risco de falhas, retrabalho e desvios de planejamento.”', N'01 - Imagens/02 - Depois/7723.jpeg', N' “Gestão à vista da reforma implantada, garantindo transparência, acompanhamento e controle das etapas executadas.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Poblema de informaçao resolvido', N'A implantação da gestão à vista é essencial para garantir acompanhamento contínuo das reformas, evitando falhas, retrabalho e perda de alinhamento entre as equipes.”', 0, NULL, N'Seal water supplied to all pumps with no leaks present', '2026-01-27T00:00:00.000', '2026-01-28T16:31:49.000', N'550508', NULL, 1);
