INSERT INTO #PVC VALUES (7728, N'81054991', N'81017050', N'Identificação de calços', NULL, N'Others/Outros', N'Foi confeccionado placas de sinalização dos suportes dos calços dos equipamentos na areia do U&M320', N'identificar/ organizar', N'0', N'01 - Imagens/01 - Antes/7728.jpeg', N'Não tinha identificação para o suporte dos calços e os mesmos ficavam desorganizado e feita a solicitação para gerar placas de identificação dos mesmos', N'01 - Imagens/02 - Depois/7728.jpeg', N'Após a realização das placas os calços passou a ser organizado de forma mais eficiente e visível.', NULL, N'O problema da desorganização dos calços foi resolvido com sucesso', N'organização', 0, NULL, N'Goal accomplished', '2026-01-28T00:00:00.000', '2026-01-29T04:07:19.000', N'81054991', NULL, 1);
INSERT INTO #PVC VALUES (7729, N'81053608', N'81053608', N' lavagem do box ', NULL, N'Open Pit/Poço aberto', N'Oficina centralizada sem agua encanada com pressão para lavar oficina, sendo necessário o auxilio de um caminhão pipa que nem sempre tem disponibilidade', N'realizar a limpeza do box e lavar perifericos', N'0', N'01 - Imagens/01 - Antes/7729.jpeg', N'Oficina centralizada sem agua encanada com pressão para lavar oficina, sendo necessário o auxilio de um caminhão pipa que nem sempre tem disponibilidade', N'01 - Imagens/02 - Depois/7729.jpeg', N'Hoje temos uma bomba d''água que secciona do totebim possibilitando a lavar oficina e periféricos ', NULL, N'Sim, pois temos o recuso que atende nossas necessidades e demandas', N'criatividade para procurar soluções para área visando segurança e agilidade', 0, NULL, N'Melhora na percepção de identidade da área, informação mais acessível para acompanhamento do próprio Time.', '2026-01-28T00:00:00.000', '2026-01-29T04:30:26.000', N'81053608', NULL, 1);
