INSERT INTO #PVC VALUES (7736, N'1008463', N'460565', N'New seal water header labeling', NULL, N'No Replication/Sem replicação', N'Major process water leak in Cu Ew.', N'No process water leak in the building', N'10112', N'01 - Imagens/01 - Antes/7736.jpeg', N'Major process water leak in Cu Ew', N'01 - Imagens/02 - Depois/7736.jpeg', N'A new process water header was installed, which bypassed the bad section of the line.  Labeling was put on the header indicating what each take off on the header was supplying', NULL, N'There are no longer any process water leaks in the building', N'None', 0, NULL, N'cuidado com um todo ', '2026-01-27T00:00:00.000', '2026-01-29T08:19:03.000', N'1008463', NULL, 1);
INSERT INTO #PVC VALUES (7737, N'553135', N'81016943', N'MELHORIA NO ABASTECIMENTO DE ELC - CA''s', NULL, N'Others/Outros', N'ANTES O ABASTECIMENTO ERA REALIZADO NA PARTE SUPERIOR DA MÁQUINA, EXPONDO O EMPREGADO AO RISCO DE QUEDA E ERGONOMICO. O EMPREGADO TAMBÉM ERA EXPOSTO AO RISCO DE QUEIMADURAS PELO ELC ', N'REDUZIR A EXPOSIÇÃO DO EMPREGADO AO RISCO DE QUEIMADURAS, QUEDAS, RISCO ERGONOMICO', N'10139', N'01 - Imagens/01 - Antes/7737.jpeg', N'ANTES O ABASTECIMENTO ERA REALIZADO NA PARTE SUPERIOR DA MÁQUINA, EXPONDO O EMPREGADO AO RISCO DE QUEDA E ERGONOMICO. O EMPREGADO TAMBÉM ERA EXPOSTO AO RISCO DE QUEIMADURAS PELO ELC ', N'01 - Imagens/02 - Depois/7737.jpeg', N'FOI REALIZADO A MUDANÇA DO LOCAL DE ABASTECIMENTO DE ELC, ASSIM TIRANDO O EMPREGADO DOS RISCOS DE QUEDA, ERGONOMICO E QUEIMADURAS. O LOCAL DE ABASTECIMENTO FOI TRANSFERIDO PARA A PARTE INFERIOR DA MÁQUINA. ', NULL, N'ANTES O ABASTECIMENTO ERA REALIZADO NA PARTE SUPERIOR DA MÁQUINA, EXPONDO O EMPREGADO AO RISCO DE QUEDA E ERGONOMICO. O EMPREGADO TAMBÉM ERA EXPOSTO AO RISCO DE QUEIMADURAS PELO ELC ', N'OBSSEÇÃO POR SEGURANÇA ', 0, NULL, N'OTIMIZAÇÃO DO TEMPO DE CHECAGEM DA FALHA  NA TELA ', '2026-01-26T00:00:00.000', '2026-01-29T09:30:16.000', N'553135', NULL, 1);
INSERT INTO #PVC VALUES (7738, N'81011242', N'81047743', N'Máquina Água Pura ', NULL, N'Others/Outros', N'A equipe realizava a limpeza de fachadas utilizando extensores, mangueiras e limpador multiuso, o que demandava maior tempo de execução e aumentava a exposição ao risco de fadiga física, devido ao esforço repetitivo e à postura prolongada durante a atividade.', N'A "Água Pura" é um equipamento voltado para a limpeza de vidros e superfícies não porosas, utilizando água 100% purificada. O sistema opera por meio de extensores que permitem alcançar áreas de até 16 metros de altura, garantindo uma limpeza eficiente, segura e sem a necessidade de produtos químicos.', N'10017', N'01 - Imagens/01 - Antes/7738.jpeg', N'A equipe realizava a limpeza de fachadas utilizando extensores, mangueiras e limpador multiuso, o que demandava maior tempo de execução e aumentava a exposição ao risco de fadiga física, devido ao esforço repetitivo e à postura prolongada durante a atividade.', N'01 - Imagens/02 - Depois/7738.jpeg', N'Foi implantado o equipamento Água Pura para a limpeza de vidros e superfícies não porosas, utilizando água 100% purificada e um sistema de extensores com alcance de até 16 metros de altura. A solução proporciona uma redução de até 75% no tempo de limpeza, elimina o uso de produtos químicos, não deixa marcas nos vidros e opera com baixa pressão. Com isso, garante mais segurança, agilidade, qualidade no serviço e menor esforço físico para as colaboradoras.', NULL, N'A solução implantada atendeu plenamente à meta inicial de modernizar o processo de limpeza de fachadas e vidros. A substituição dos métodos manuais (extensores, mangueiras e limpador multiuso) pela Máquina Água Pura solucionou os principais problemas identificados:
INSERT INTO #PVC VALUES (7739, N'81002390', N'81002390', N'Reutilização de Garrafas com Alças Ergonômicas Reforçadas', NULL, N'Others/Outros', N'As garrafas térmicas utilizadas na área apresentavam recorrência de quebra das alças originais devido ao tempo de uso, exposição ao sol e ressecamento do material. Com as alças danificadas ou ausentes, as garrafas cheias eram carregadas segurando-as pelo corpo, o que deslocava o peso para frente, gerando desconforto ergonômico, risco de lesão e aumentando a probabilidade de queda da garrafa.', N'Redução do risco de fadiga muscular e desconforto ao colaborador, redução do risco de acidentes por queda de garrafas devido à falta de alças, redução de custos com aquisição de novas garrafas', N'10361', N'01 - Imagens/01 - Antes/7739.jpeg', N'As garrafas térmicas utilizadas na área apresentavam recorrência de quebra das alças originais devido ao tempo de uso, exposição ao sol e ressecamento do material. Com as alças danificadas ou ausentes, as garrafas cheias eram carregadas segurando-as pelo corpo, o que deslocava o peso para frente, gerando desconforto ergonômico, risco de lesão e aumentando a probabilidade de queda da garrafa.', N'01 - Imagens/02 - Depois/7739.jpeg', N'Para reaproveitar as garrafas ainda funcionais e eliminar a condição insegura, foram implementadas novas alças confeccionadas com corda resistente, revestidas com mangueira de borracha para maior conforto e firmeza no transporte. Essa solução prolonga a vida útil das garrafas, evita o descarte desnecessário e proporciona melhor ergonomia e segurança aos colaboradores durante o manuseio.', NULL, N'Sim', N'Reaproveitamento', 0, NULL, N'Garantir comunicação mais rápida, clara e padronizada da programação de desmonte, reduzindo erros e o tempo de atualização da placa.', '2026-01-28T00:00:00.000', '2026-01-29T09:52:07.000', N'81002390', NULL, 1);
INSERT INTO #PVC VALUES (7740, N'501925', N'501925', N'CÁLCULO PARA FREQUÊNCIA DE DEFEITO ELÉTRICO DYNAMOX', NULL, N'Others/Outros', N'ANTES ERA REALIZADO O CADASTRO DA FREQUÊNCIA DE DEFEITO ELÉTRICO COM O VALOR DE 120HZ, O QUE ERA INEFICIENTE PARA ANÁLISE DE MOTORES COM ROTAÇÃO VARIÁVEL. A FREQUÊNCIA VARIA MUITO DO VALOR DE 120HZ.', N'IDENTIFICAR A FREQUÊNCIA DE DEFEITO ELÉTRICO EM MOTORES DE ROTAÇÃO VARIÁVEL', N'10178', N'01 - Imagens/01 - Antes/7740.jpeg', N'Para diagnóstco de defeitos elétricos era considerada a frequência de  120HZ, porém os equipamentos da flotação possuem rotação variável, sendo necessário calcular manualmente as frequências de falha em função da RPM no instante da coleta.
INSERT INTO #PVC VALUES (7741, N'81017062', N'300658', N'New throat bar covers', NULL, N'Underground/Subterrâneo', N'Existing throat bar covers are difficult to install and prone to corrosion decreasing maintenance productivity', N'Maintenance Productivity Improvement', N'10238', N'01 - Imagens/01 - Antes/7741.jpeg', N'Old covers prone to corrosion making it difficult to install and remove decreasing maintenance productivity', N'01 - Imagens/02 - Depois/7741.jpeg', N'New covers use tapered wedges to lock instead of threads, preventing corrosion', NULL, N'Goal accomplished', N'Good work team', 0, NULL, N'Redução de tempo para iniciar a atividade e tempo de exposição de deslocamento dentro da mina. ', '2026-01-27T00:00:00.000', '2026-01-29T11:41:11.000', N'81017062', NULL, 1);
INSERT INTO #PVC VALUES (7742, N'81007480', N'544568', N'Relatório Integrado de CAPEX e OPEX', NULL, N'Projects/Projetos', N'Relatórios de CAPEX e OPEX eram gerados em bases distintas, com padrões diferentes, o usuário acessava 2 plataformas para acompanhar. A atualização consumia tempo e tinha risco de inconsistências.', N'Integrar os relatórios de CAPEX e OPEX em uma única plataforma padronizada', N'0', N'01 - Imagens/01 - Antes/7742.jpeg', N'Os usuários acompanhavam os gastos de OPEX pelo BI e recebiam CAPEX por e mail com imagens e anexos do excel. Os formatos distintos geravam desconforto visual e dificultavam o acesso às informações.', N'01 - Imagens/02 - Depois/7742.jpeg', N'CAPEX e OPEX passaram a ser consolidados em uma plataforma única e padronizada, eliminando a consolidação manual, reduzindo tempo de atualização e aumentando a confiabilidade e agilidade para o usuário.', N'https://app.powerbi.com/groups/me/apps/324ad6c5-57f4-4a3b-8805-0d2b8ab29ff3/reports/e33f4391-66ca-4d2a-913d-1148490d7c75/35fc33daed0d716d76cd?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim, foi resolvido. CAPEX e OPEX estão no BI com atualização diária; o usuário navega facilmente nas duas visões, sem risco de erro humano na atualização, e o report por e‑mail segue layout padronizado.', N'Visões e plataforma padronizados otimizam tempo para análise e decisão. Automatizar a atualização melhora a rotina. O mesmo padrão e layout permite uma leitura mais agradável.', 0, NULL, N'Reutilização de recursos que seriam descartados para confecção de uma tampa, evitando a compra de uma tampa no valor de ', '2025-10-31T00:00:00.000', '2026-01-29T12:48:31.000', N'81007480', NULL, 1);
INSERT INTO #PVC VALUES (7743, N'81047115', N'81018181', N'KIT BLINDAGEM', NULL, N'Others/Outros', N'ANTES O EQUIPAMENTO APRESENTAVA ALTO RISCO DE CONTAMINAÇÃO OCASIONANDO A TROCA DO LUBRIFICANTE ANTES DO RECOMENDADO.', N'REDUÇÃO DE CONTAMINAÇÃO', N'10362', N'01 - Imagens/01 - Antes/7743.jpeg', N'ANTES O EQUIPAMENTO APRESENTAVA ALTO RISCO DE CONTAMINAÇÃO OCASIONANDO A TROCA DO LUBRIFICANTE ANTES DO RECOMENDADO.', N'01 - Imagens/02 - Depois/7743.jpeg', N'REALIZADOA APLICAÇÃO DE UM KIT BLINDAGEM NO  CARTE DA BA AFIM DE ELIMINAR  POSSIVEIS FOCOS DE CONTAMINAÇÃO E APLICADO NO EQUALIZADOR DE PRESSÃO E UM DOZADOR DE OLEO.', NULL, N'SIM', N'SETIMENTO DE DONO', 0, NULL, N'sim, pessoas alertadas sobre movimentação.', '2026-01-26T00:00:00.000', '2026-01-29T14:39:50.000', N'81047115', NULL, 1);
