INSERT INTO #PVC VALUES (7924, N'606854', N'300637', N'Shop Pit Crossover Platform improvement', NULL, N'Others/Outros', N'The existing shop pit crossover platform visibility was poor and track control protocol was unclear.', N'Improve Visibility and Track Controls', N'0', N'01 - Imagens/01 - Antes/7924.jpeg', N'The existing crossover platform is supported on the rails. If a locomotive is unaware of the platform location and passes overtop of it, damages occur to the platform and the risk of a derailment increases.', N'01 - Imagens/02 - Depois/7924.jpeg', N'A new flag w/ magnet will be mounted at the crossover platform location(s) to control traffic and improve visibility and alert operators.', NULL, N'YES improved awareness of presence of walkway', N'improve routines ', 0, NULL, N'Gerou o resultado melhor do que esperado. Antes era uma demanda que requeria bastante tempo.', '2026-01-30T00:00:00.000', '2026-02-03T16:47:47.000', N'606854', NULL, 1);
